window.SA_WORKER_BLOB_URL = URL.createObjectURL(
  new Blob(["// --- src/constants.js ---\n// src/constants.js — Shared constants for the Body Optimizer.\n// Loaded BEFORE app.js so other scripts can read these as top-level identifiers.\n\n// localStorage keys\nconst STATE_KEY       = 'idle_directive_state';\nconst SETTINGS_KEY    = 'app_settings';\nconst REOPT_STATS_KEY = 'bg_reopt_stats';\n\n// Optimization tuning\nconst MAX_THREADS = 6;\n\n\n// --- src/optimizer/rotation.js ---\n// src/optimizer/rotation.js — Component rotation primitives.\n// Pure geometry: no UI, no state, no DOM. Safe to share between main and worker.\n\nconst ROT_ORDER = ['N','E','S','W'];\n\nfunction rotateSide(side, deg) {\n  const steps = ((deg / 90) % 4 + 4) % 4;\n  return ROT_ORDER[(ROT_ORDER.indexOf(side) + steps) % 4];\n}\n\nfunction rotateCoord(r, c, maxR, maxC, deg) {\n  if (deg === 0)   return [r, c];\n  if (deg === 90)  return [c, maxR - r];\n  if (deg === 180) return [maxR - r, maxC - c];\n  if (deg === 270) return [maxC - c, r];\n}\n\nfunction rotateComponent(compDef, deg) {\n  if (deg === 0) {\n    return {\n      shape: compDef.shape.map(c => [...c]),\n      energyPorts: compDef.energyPorts.map(p => ({ cell: [...p.cell], side: p.side }))\n    };\n  }\n\n  const maxR = Math.max(...compDef.shape.map(([r]) => r));\n  const maxC = Math.max(...compDef.shape.map(([,c]) => c));\n\n  let shape = compDef.shape.map(([r,c]) => rotateCoord(r, c, maxR, maxC, deg));\n  let ports = compDef.energyPorts.map(p => ({\n    cell: rotateCoord(p.cell[0], p.cell[1], maxR, maxC, deg),\n    side: rotateSide(p.side, deg)\n  }));\n\n  // Normalize to origin (min row/col = 0)\n  const minR = Math.min(...shape.map(([r]) => r));\n  const minC = Math.min(...shape.map(([,c]) => c));\n  shape = shape.map(([r,c]) => [r - minR, c - minC]);\n  ports = ports.map(p => ({ cell: [p.cell[0] - minR, p.cell[1] - minC], side: p.side }));\n\n  return { shape, energyPorts: ports };\n}\n\nfunction rotatePeriShape(periShape, deg) {\n  if (deg === 0) return periShape.map(c => [...c]);\n  const maxR = Math.max(...periShape.map(([r]) => r));\n  const maxC = Math.max(...periShape.map(([,c]) => c));\n  let s = periShape.map(([r,c]) => rotateCoord(r, c, maxR, maxC, deg));\n  const minR = Math.min(...s.map(([r]) => r));\n  const minC = Math.min(...s.map(([,c]) => c));\n  return s.map(([r,c]) => [r - minR, c - minC]);\n}\n\nfunction getBounds(shape) {\n  return {\n    height: Math.max(...shape.map(([r]) => r)) + 1,\n    width:  Math.max(...shape.map(([,c]) => c)) + 1\n  };\n}\n\n// Returns rotations that are distinct in either shape OR port configuration.\n// Square components (like battery_2x2) have shape-identical rotations, but\n// their PORT directions still rotate — so all 4 rotations are kept if they\n// produce different port layouts. This lets the optimizer face an energy\n// port directly at the bus, saving wires.\n//\n// Symmetry tiers:\n//   - asymmetric shape, multiple ports: usually 4 rotations\n//   - square + 1 port: 4 rotations (port direction differs each step)\n//   - square + symmetric ports (e.g. 2 opposite): 2 rotations\n//   - rectangle + ports preserved across 180°: 2 rotations\n//   - fully symmetric (rare): 1 rotation\nconst _uniqueRotsCache = new Map();\nfunction getUniqueDegs(def) {\n  if (_uniqueRotsCache.has(def.id)) return _uniqueRotsCache.get(def.id);\n  const seen = new Set();\n  const result = [];\n  for (const deg of [0, 90, 180, 270]) {\n    const { shape, energyPorts } = rotateComponent(def, deg);\n    const shapeKey = shape.map(([r,c]) => `${r},${c}`).sort().join('|');\n    const eKey = (energyPorts || []).map(p => `${p.cell[0]},${p.cell[1]},${p.side}`).sort().join('|');\n    const key = `${shapeKey}#${eKey}`;\n    if (!seen.has(key)) { seen.add(key); result.push(deg); }\n  }\n  _uniqueRotsCache.set(def.id, result);\n  return result;\n}\n\n\n// --- src/optimizer/bus.js ---\n// src/optimizer/bus.js — Power propagation and wire pathfinding.\n// Direction constants (SIDE_DELTA, OPPOSITE), BFS from buses to powered set,\n// and findWirePath used by tryAddWires + the main-thread placement logic.\n\nconst SIDE_DELTA = { N:{dr:-1,dc:0}, S:{dr:1,dc:0}, E:{dr:0,dc:1}, W:{dr:0,dc:-1} };\nconst OPPOSITE   = { N:'S', S:'N', E:'W', W:'E' };\n\n// BFS from buses to find all powered placement indices\nfunction computePoweredSet(placements, gridRows, gridCols) {\n  const portMap = new Map();\n  placements.forEach((p, idx) => {\n    p.rotatedPorts.forEach(({ cell, side }) => {\n      const key = `${p.row+cell[0]},${p.col+cell[1]},${side}`;\n      if (!portMap.has(key)) portMap.set(key, []);\n      portMap.get(key).push(idx);\n    });\n  });\n\n  const powered = new Set();\n  const queue = [];\n\n  // Seed: ports directly touching a bus\n  placements.forEach((p, idx) => {\n    p.rotatedPorts.forEach(({ cell, side }) => {\n      const gr = p.row + cell[0], gc = p.col + cell[1];\n      const onBus = (side === 'W' && gc === 0) || (side === 'S' && gr === gridRows - 1);\n      if (onBus && !powered.has(idx)) {\n        powered.add(idx);\n        queue.push(idx);\n      }\n    });\n  });\n\n  // BFS: propagate through port-to-port connections\n  while (queue.length) {\n    const idx = queue.shift();\n    const p = placements[idx];\n    p.rotatedPorts.forEach(({ cell, side }) => {\n      const gr = p.row + cell[0], gc = p.col + cell[1];\n      const d = SIDE_DELTA[side];\n      const adjKey = `${gr+d.dr},${gc+d.dc},${OPPOSITE[side]}`;\n      if (portMap.has(adjKey)) {\n        portMap.get(adjKey).forEach(adjIdx => {\n          if (!powered.has(adjIdx)) {\n            powered.add(adjIdx);\n            queue.push(adjIdx);\n          }\n        });\n      }\n    });\n  }\n\n  return powered;\n}\n\n// Priority 1: check connection to another powered component's port\nfunction wouldConnectToComponent(rotatedPorts, row, col, placements, poweredSet) {\n  const poweredPortKeys = new Set();\n  placements.forEach((p, idx) => {\n    if (!poweredSet.has(idx)) return;\n    p.rotatedPorts.forEach(({ cell, side }) => {\n      poweredPortKeys.add(`${p.row+cell[0]},${p.col+cell[1]},${side}`);\n    });\n  });\n  for (const { cell, side } of rotatedPorts) {\n    const gr = row + cell[0], gc = col + cell[1];\n    const d = SIDE_DELTA[side];\n    if (poweredPortKeys.has(`${gr+d.dr},${gc+d.dc},${OPPOSITE[side]}`)) return true;\n  }\n  return false;\n}\n\n// Priority 2: check direct bus connection\nfunction wouldConnectToBus(rotatedPorts, row, col, gridRows, gridCols) {\n  for (const { cell, side } of rotatedPorts) {\n    const gr = row + cell[0], gc = col + cell[1];\n    if ((side === 'W' && gc === 0) || (side === 'S' && gr === gridRows - 1)) return true;\n  }\n  return false;\n}\n\n// Combined check used by addComponent\nfunction wouldBePowered(rotatedPorts, row, col, placements, poweredSet, gridRows, gridCols) {\n  return wouldConnectToBus(rotatedPorts, row, col, gridRows, gridCols) ||\n         wouldConnectToComponent(rotatedPorts, row, col, placements, poweredSet);\n}\n\n// findWirePath: BFS through free cells from the placement's port frontier\n// outward toward power frontier (bus edge or existing powered-component port).\n// Returns the cell sequence for the wire chain, or null if unreachable.\nfunction findWirePath(rotatedShape, rotatedPorts, row, col, state) {\n  const { grid, placements } = state;\n  const poweredSet = computePoweredSet(placements, grid.rows, grid.cols);\n\n  const occupied = new Set();\n  placements.forEach(p => p.rotatedShape.forEach(([r,c]) => occupied.add(`${p.row+r},${p.col+c}`)));\n  addPeripheralReserved(placements, occupied);\n  rotatedShape.forEach(([r,c]) => occupied.add(`${row+r},${col+c}`));\n\n  // Power frontier: empty cells where a wire would be immediately powered\n  const powerFrontier = new Set();\n  for (let r = 0; r < grid.rows; r++) {\n    const k = `${r},0`;\n    if (!occupied.has(k)) powerFrontier.add(k);\n  }\n  for (let c = 0; c < grid.cols; c++) {\n    const k = `${grid.rows-1},${c}`;\n    if (!occupied.has(k)) powerFrontier.add(k);\n  }\n  placements.forEach((p, idx) => {\n    if (!poweredSet.has(idx)) return;\n    p.rotatedPorts.forEach(({ cell, side }) => {\n      const gr = p.row + cell[0], gc = p.col + cell[1];\n      const d = SIDE_DELTA[side];\n      const ar = gr + d.dr, ac = gc + d.dc;\n      if (ar >= 0 && ar < grid.rows && ac >= 0 && ac < grid.cols) {\n        const k = `${ar},${ac}`;\n        if (!occupied.has(k)) powerFrontier.add(k);\n      }\n    });\n  });\n\n  // Target frontier: empty cells adjacent (outward) to the new component's ports\n  const targetFrontier = new Set();\n  for (const { cell, side } of rotatedPorts) {\n    const gr = row + cell[0], gc = col + cell[1];\n    const d = SIDE_DELTA[side];\n    const ar = gr + d.dr, ac = gc + d.dc;\n    if (ar >= 0 && ar < grid.rows && ac >= 0 && ac < grid.cols) {\n      const k = `${ar},${ac}`;\n      if (!occupied.has(k)) targetFrontier.add(k);\n    }\n  }\n\n  if (targetFrontier.size === 0) return null;\n\n  // Quick check: target-frontier cell that is also a power-frontier cell needs just 1 wire\n  for (const t of targetFrontier) {\n    if (powerFrontier.has(t)) return [t.split(',').map(Number)];\n  }\n\n  // BFS: from target frontier outward toward power frontier\n  const visited = new Map();\n  const queue = [];\n  for (const t of targetFrontier) { visited.set(t, null); queue.push(t); }\n\n  while (queue.length > 0) {\n    const current = queue.shift();\n    const [r, c] = current.split(',').map(Number);\n\n    for (const [dr, dc] of [[-1,0],[1,0],[0,-1],[0,1]]) {\n      const nr = r+dr, nc = c+dc;\n      if (nr < 0 || nr >= grid.rows || nc < 0 || nc >= grid.cols) continue;\n      const k = `${nr},${nc}`;\n      if (occupied.has(k) || visited.has(k)) continue;\n\n      visited.set(k, current);\n\n      if (powerFrontier.has(k)) {\n        const path = [k];\n        let p = visited.get(k);\n        while (p !== null) { path.push(p); p = visited.get(p); }\n        return path.map(s => s.split(',').map(Number));\n      }\n\n      queue.push(k);\n    }\n  }\n\n  return null;\n}\n\n\n// --- src/optimizer/placement.js ---\n// src/optimizer/placement.js — Placement geometry helpers.\n// Map-of-occupied-cells, overlap and bounds checks. Pure functions.\n// Note: addPeripheralReserved depends on SIDE_DELTA from bus.js — loaded later.\n\nfunction getOccupiedMap(placements) {\n  const map = new Map();\n  placements.forEach((p, idx) => {\n    p.rotatedShape.forEach(([r,c]) => map.set(`${p.row+r},${p.col+c}`, idx));\n  });\n  return map;\n}\n\nfunction hasOverlap(shape, row, col, occupiedMap) {\n  return shape.some(([r,c]) => occupiedMap.has(`${row+r},${col+c}`));\n}\n\nfunction fitsInGrid(shape, row, col, gridRows, gridCols) {\n  return shape.every(([r,c]) => {\n    const gr = row+r, gc = col+c;\n    return gr >= 0 && gr < gridRows && gc >= 0 && gc < gridCols;\n  });\n}\n\n// Reserves peripheral cells (e.g., Biocell attached to Bio Generator) and one\n// extra cell in the same direction onto the supplied \"occupied\" Set.\n// Used by findWirePath and computeFreeSpaceQuality to keep wires/components\n// out of slots reserved for auto-placed peripherals.\nfunction addPeripheralReserved(placements, occupied) {\n  placements.forEach(p => {\n    if (!p.rotatedPeripheral) return;\n    const peri = p.rotatedPeripheral;\n    const d = SIDE_DELTA[peri.port.side];\n    const startR = p.row + peri.port.cell[0] + d.dr;\n    const startC = p.col + peri.port.cell[1] + d.dc;\n    peri.shape.forEach(([r, c]) => occupied.add(`${startR + r},${startC + c}`));\n    occupied.add(`${startR + d.dr},${startC + d.dc}`);\n  });\n}\n\n\n// --- src/optimizer/score.js ---\n// src/optimizer/score.js — Scoring and quality metrics.\n// computeFreeSpaceQuality (used by scoreLayout and findBestPlacement) measures\n// connectivity of remaining empty cells. computeWorkingSet identifies\n// Spinners satisfied by their Repeater requirements. scoreLayout combines\n// these into the brute force's final layout ranking.\n\n// Player-tunable weights (13 total) for scoreLayout's signals (Settings modal).\n// Each JS context (main thread, each SA worker) holds its own copy — the\n// main thread calls setScoreWeights() directly from persisted settings;\n// workers receive the current values via the 'init' message, since threads\n// don't share memory. See src/ui/settings.js and sa-worker.js.\nconst DEFAULT_SCORE_WEIGHTS = {\n  workingSet:              2650000, // per working Spinner\n  wirePenalty:               100000, // per auto-routed wire cell (subtracted) — raised from 5000 (v=149) so SA favors compact, wire-free placement over maximizing open space, per user request\n  quality:                   15000, // per unit of free-neighbour connectivity\n  freeBlock:                   0.2, // multiplier on computeFreeBlockBonus's \"free\" total (any accessible open rectangle) — lowered from 1 (v=149), same reasoning as wirePenalty above\n  busAccess:                     1, // multiplier on computeFreeBlockBonus's \"bus\" total (extra, only for rectangles touching the W/S bus)\n  cluster:                   50000, // per same-type neighbour pair (port-connected pairs get x2)\n  amplifier:               4000000, // per Power Amplifier <-> Harvester/Salvager port connection\n  batteryAmplifier:        1000000, // per Battery Amplifier <-> battery cell of area (multiplied by the connected battery's cell count)\n  energyAmpBioGen:         3000000, // per Energy Amplifier <-> Bio Generator/Bio Generator (II) port connection\n  energyAmpEnergyCells:    3000000, // per Energy Amplifier <-> Energy Cells port connection\n  energyAmpSpinner:        3000000, // per Energy Amplifier <-> Spinner port connection\n  energyAmpPulser:         3000000, // per Energy Amplifier <-> Pulser port connection\n  concentrator:            3000000  // per Concentrator <-> Energy Cells port connection\n};\nlet scoreWeights = { ...DEFAULT_SCORE_WEIGHTS };\n\nfunction setScoreWeights(w) {\n  scoreWeights = { ...DEFAULT_SCORE_WEIGHTS, ...(w || {}) };\n}\n\nfunction getScoreWeights() {\n  return { ...scoreWeights };\n}\n\nfunction computeFreeSpaceQuality(extraShape, extraRow, extraCol, placements, gridRows, gridCols) {\n  const occupied = new Set();\n  placements.forEach(p => p.rotatedShape.forEach(([r,c]) => occupied.add(`${p.row+r},${p.col+c}`)));\n  addPeripheralReserved(placements, occupied);\n  if (extraShape && extraShape.length > 0) {\n    extraShape.forEach(([r,c]) => occupied.add(`${extraRow+r},${extraCol+c}`));\n  }\n\n  let quality = 0;\n  for (let r = 0; r < gridRows; r++) {\n    for (let c = 0; c < gridCols; c++) {\n      if (occupied.has(`${r},${c}`)) continue;\n      let freeNeighbours = 0;\n      [[-1,0],[1,0],[0,-1],[0,1]].forEach(([dr,dc]) => {\n        const nr = r+dr, nc = c+dc;\n        if (nr >= 0 && nr < gridRows && nc >= 0 && nc < gridCols && !occupied.has(`${nr},${nc}`)) {\n          freeNeighbours++;\n        }\n      });\n      quality += freeNeighbours;\n    }\n  }\n  return quality;\n}\n\n// Returns indices of components whose timing/working conditions are satisfied.\n// Spinner needs repeater_2s on any side, OR repeater_4s on 2+ distinct sides.\nfunction computeWorkingSet(placements) {\n  const working = new Set();\n\n  const portMap = new Map();\n  placements.forEach((p, idx) => {\n    p.rotatedPorts.forEach(({ cell, side }) => {\n      const key = `${p.row+cell[0]},${p.col+cell[1]},${side}`;\n      if (!portMap.has(key)) portMap.set(key, []);\n      portMap.get(key).push(idx);\n    });\n  });\n\n  placements.forEach((p, idx) => {\n    if (p.componentId !== 'spinner') return;\n\n    const connected2s = new Set();\n    const connected4sBySide = new Map();\n\n    p.rotatedPorts.forEach(({ cell, side }) => {\n      const gr = p.row + cell[0], gc = p.col + cell[1];\n      const d  = SIDE_DELTA[side];\n      const adjKey = `${gr+d.dr},${gc+d.dc},${OPPOSITE[side]}`;\n      if (!portMap.has(adjKey)) return;\n      portMap.get(adjKey).forEach(adjIdx => {\n        const id = placements[adjIdx].componentId;\n        if (id === 'repeater_2s') connected2s.add(adjIdx);\n        if (id === 'repeater_4s') {\n          if (!connected4sBySide.has(side)) connected4sBySide.set(side, new Set());\n          connected4sBySide.get(side).add(adjIdx);\n        }\n      });\n    });\n\n    if (connected2s.size >= 1)       { working.add(idx); return; }\n    if (connected4sBySide.size >= 2) { working.add(idx); return; }\n  });\n\n  return working;\n}\n\n// Powered free-block bonus table — escalates with block area so SA prefers\n// to leave large open rectangles. The numbers are calibrated so that:\n//   - small (2x2) blocks are cheap (200 each) — pure capacity placeholders;\n//   - mid (3x3) blocks are valuable (~1 wire = 5000 saved);\n//   - large (4x4) blocks dominate (~half a working spinner = 25000).\n// Overlap is intentional: a 4x4 powered area at the bus contains nine 2x2\n// windows + four 3x3s + one 4x4, all counted, so larger areas scale\n// super-linearly without any explicit max-rectangle dedup.\nconst FREE_BLOCK_BONUS = {\n  '2x2':   200,\n  '3x2':  1000, '2x3':  1000,\n  '3x3':  5000,\n  '4x3': 12000, '3x4': 12000,\n  '4x4': 25000,\n  '5x4': 40000, '4x5': 40000,\n  '5x5': 60000,\n  '6x4': 60000, '4x6': 60000\n};\nconst FREE_BLOCK_SIZES = [\n  [6,4],[4,6],[5,5],[5,4],[4,5],[4,4],[4,3],[3,4],[3,3],[3,2],[2,3],[2,2]\n];\n\n// Returns two independently-weighted totals for large, accessible rectangles\n// of empty cells (see scoreLayout):\n//   free — every accessible window's base bonus. \"Accessible\" means at\n//          least one cell is on the W/S bus OR adjacent to a placed\n//          component's port (so a future battery/cluster put there could\n//          be powered — with a short wire, in the port-adjacent case).\n//   bus  — the SAME base bonus again, but ONLY for windows that touch the\n//          W (col=0) or S (row=R-1) bus directly, where the future\n//          component could be powered with NO wire at all. Separate from\n//          `free` so the two are independently tunable (Settings) instead\n//          of one hardcoded multiplier.\nfunction computeFreeBlockBonus(placements, gridRows, gridCols) {\n  const rows = gridRows, cols = gridCols;\n  // Uint8 grids beat Set lookups by 10-20× in tight SA inner loops.\n  const occupied   = new Uint8Array(rows * cols);\n  const portTarget = new Uint8Array(rows * cols);\n\n  for (const p of placements) {\n    if (p.rotatedShape) {\n      for (const [r, c] of p.rotatedShape) {\n        const gr = p.row + r, gc = p.col + c;\n        if (gr >= 0 && gr < rows && gc >= 0 && gc < cols) occupied[gr * cols + gc] = 1;\n      }\n    }\n    if (p.rotatedPeripheral) {\n      const peri = p.rotatedPeripheral;\n      const d = SIDE_DELTA[peri.port.side];\n      const sR = p.row + peri.port.cell[0] + d.dr;\n      const sC = p.col + peri.port.cell[1] + d.dc;\n      for (const [r, c] of peri.shape) {\n        const gr = sR + r, gc = sC + c;\n        if (gr >= 0 && gr < rows && gc >= 0 && gc < cols) occupied[gr * cols + gc] = 1;\n      }\n    }\n    if (p.componentId === 'wire') continue; // wires don't 'power' a free block\n    for (const port of (p.rotatedPorts || [])) {\n      const gr = p.row + port.cell[0];\n      const gc = p.col + port.cell[1];\n      const d = SIDE_DELTA[port.side];\n      const tr = gr + d.dr, tc = gc + d.dc;\n      if (tr >= 0 && tr < rows && tc >= 0 && tc < cols) portTarget[tr * cols + tc] = 1;\n    }\n  }\n\n  let free = 0;\n  let bus  = 0;\n  for (const [h, w] of FREE_BLOCK_SIZES) {\n    const base = FREE_BLOCK_BONUS[`${h}x${w}`];\n    if (!base) continue;\n    const maxR = rows - h, maxC = cols - w;\n    for (let r = 0; r <= maxR; r++) {\n      for (let c = 0; c <= maxC; c++) {\n        // 1) All cells of the window must be free.\n        let allFree = true;\n        for (let dr = 0; dr < h && allFree; dr++) {\n          const rowBase = (r + dr) * cols + c;\n          for (let dc = 0; dc < w; dc++) {\n            if (occupied[rowBase + dc]) { allFree = false; break; }\n          }\n        }\n        if (!allFree) continue;\n        // 2) At least one cell must be on a bus or fed by a placed port.\n        let powered = false;\n        for (let dr = 0; dr < h && !powered; dr++) {\n          const cellR = r + dr;\n          const onSBus = (cellR === rows - 1);\n          for (let dc = 0; dc < w; dc++) {\n            const cellC = c + dc;\n            if (cellC === 0 || onSBus || portTarget[cellR * cols + cellC]) {\n              powered = true; break;\n            }\n          }\n        }\n        if (!powered) continue;\n        free += base;\n        // 3) Windows touching the bus directly ALSO earn the separate bus total.\n        const busTouch = (c === 0 || r + h - 1 === rows - 1);\n        if (busTouch) bus += base;\n      }\n    }\n  }\n  return { free, bus };\n}\n\n// Power Amplifier bonus: rewards each port-to-port connection between a\n// Power Amplifier and an adjacent Harvester or Salvager, which the\n// amplifier boosts in-game. Optional — not required for layout validity\n// (unlike Repeater<->Spinner), purely a scoring incentive so SA tries to\n// wire amplifiers up to a target when the grid allows it.\nconst AMPLIFIER_TARGETS = new Set(['harvester', 'salvager']);\n\n// All 4 amplifier-family component ids (as opposed to their targets above).\n// Reused by ensureComponentOrder (app.js) and _saComponentOrder\n// (src/sa/greedy.js) to place these BEFORE their targets — same\n// most-constrained-first reasoning as Repeater-before-Spinner and Bio\n// Generator-before-Biocell: a target placed first has no amplifier to\n// connect to yet, so it greedily grabs whatever scores best in isolation\n// (e.g. bus-adjacency) and strands the amplifier once it's finally placed.\nconst AMPLIFIER_TYPE_IDS = new Set(['power_amplifier', 'battery_amplifier', 'energy_amplifier', 'concentrator']);\n\nfunction computeAmplifierBonus(placements) {\n  const portMap = new Map();\n  for (let i = 0; i < placements.length; i++) {\n    const p = placements[i];\n    if (p.componentId !== 'power_amplifier' && !AMPLIFIER_TARGETS.has(p.componentId)) continue;\n    for (const { cell, side } of (p.rotatedPorts || [])) {\n      const key = `${p.row + cell[0]},${p.col + cell[1]},${side}`;\n      if (!portMap.has(key)) portMap.set(key, []);\n      portMap.get(key).push(i);\n    }\n  }\n\n  let bonus = 0;\n  const counted = new Set();\n  for (let i = 0; i < placements.length; i++) {\n    const p = placements[i];\n    if (p.componentId !== 'power_amplifier') continue;\n    for (const { cell, side } of (p.rotatedPorts || [])) {\n      const gr = p.row + cell[0], gc = p.col + cell[1];\n      const d = SIDE_DELTA[side];\n      const adjKey = `${gr + d.dr},${gc + d.dc},${OPPOSITE[side]}`;\n      if (!portMap.has(adjKey)) continue;\n      for (const j of portMap.get(adjKey)) {\n        if (!AMPLIFIER_TARGETS.has(placements[j].componentId)) continue;\n        const pairKey = `${i},${j}`;\n        if (counted.has(pairKey)) continue;\n        counted.add(pairKey);\n        bonus += scoreWeights.amplifier;\n      }\n    }\n  }\n  return bonus;\n}\n\n// Battery Amplifier bonus: rewards each port-to-port connection between a\n// Battery Amplifier and an adjacent battery (any battery_* component,\n// excluding another amplifier), scaled by that battery's cell count —\n// bigger batteries are worth proportionally more, matching the in-game\n// capacity-boost mechanic. Optional, like the Power Amplifier bonus — not\n// required for layout validity, purely a scoring incentive.\nfunction _isBatteryTarget(componentId) {\n  return componentId.startsWith('battery_') && componentId !== 'battery_amplifier';\n}\n\nfunction computeBatteryAmplifierBonus(placements) {\n  const portMap = new Map();\n  for (let i = 0; i < placements.length; i++) {\n    const p = placements[i];\n    if (p.componentId !== 'battery_amplifier' && !_isBatteryTarget(p.componentId)) continue;\n    for (const { cell, side } of (p.rotatedPorts || [])) {\n      const key = `${p.row + cell[0]},${p.col + cell[1]},${side}`;\n      if (!portMap.has(key)) portMap.set(key, []);\n      portMap.get(key).push(i);\n    }\n  }\n\n  let bonus = 0;\n  const counted = new Set();\n  for (let i = 0; i < placements.length; i++) {\n    const p = placements[i];\n    if (p.componentId !== 'battery_amplifier') continue;\n    for (const { cell, side } of (p.rotatedPorts || [])) {\n      const gr = p.row + cell[0], gc = p.col + cell[1];\n      const d = SIDE_DELTA[side];\n      const adjKey = `${gr + d.dr},${gc + d.dc},${OPPOSITE[side]}`;\n      if (!portMap.has(adjKey)) continue;\n      for (const j of portMap.get(adjKey)) {\n        if (!_isBatteryTarget(placements[j].componentId)) continue;\n        const pairKey = `${i},${j}`;\n        if (counted.has(pairKey)) continue;\n        counted.add(pairKey);\n        const batteryArea = (placements[j].rotatedShape || []).length;\n        bonus += scoreWeights.batteryAmplifier * batteryArea;\n      }\n    }\n  }\n  return bonus;\n}\n\n// Energy Amplifier bonus: counts each port-to-port connection between an\n// Energy Amplifier and an adjacent energy producer, broken down into four\n// independently-weighted categories (weights.energyAmpBioGen/EnergyCells/\n// Spinner/Pulser — see scoreLayout) since each producer type's boost is\n// worth a different amount to the player. Flat per connection within a\n// category — unlike the Battery Amplifier, producer \"size\" isn't scaled\n// here. Optional, like the other amplifiers — not required for layout\n// validity, and independent of the Spinner's separate Repeater\n// working-set requirement.\nconst ENERGY_AMPLIFIER_TARGETS = new Set(['bio_generator', 'bio_generator_ii', 'energy_cells', 'spinner', 'pulser']);\n\nfunction computeEnergyAmplifierBonus(placements) {\n  const portMap = new Map();\n  for (let i = 0; i < placements.length; i++) {\n    const p = placements[i];\n    if (p.componentId !== 'energy_amplifier' && !ENERGY_AMPLIFIER_TARGETS.has(p.componentId)) continue;\n    for (const { cell, side } of (p.rotatedPorts || [])) {\n      const key = `${p.row + cell[0]},${p.col + cell[1]},${side}`;\n      if (!portMap.has(key)) portMap.set(key, []);\n      portMap.get(key).push(i);\n    }\n  }\n\n  const counts = { bioGen: 0, energyCells: 0, spinner: 0, pulser: 0 };\n  const counted = new Set();\n  for (let i = 0; i < placements.length; i++) {\n    const p = placements[i];\n    if (p.componentId !== 'energy_amplifier') continue;\n    for (const { cell, side } of (p.rotatedPorts || [])) {\n      const gr = p.row + cell[0], gc = p.col + cell[1];\n      const d = SIDE_DELTA[side];\n      const adjKey = `${gr + d.dr},${gc + d.dc},${OPPOSITE[side]}`;\n      if (!portMap.has(adjKey)) continue;\n      for (const j of portMap.get(adjKey)) {\n        const targetId = placements[j].componentId;\n        if (!ENERGY_AMPLIFIER_TARGETS.has(targetId)) continue;\n        const pairKey = `${i},${j}`;\n        if (counted.has(pairKey)) continue;\n        counted.add(pairKey);\n        if (targetId === 'bio_generator' || targetId === 'bio_generator_ii') counts.bioGen++;\n        else if (targetId === 'energy_cells') counts.energyCells++;\n        else if (targetId === 'spinner') counts.spinner++;\n        else if (targetId === 'pulser') counts.pulser++;\n      }\n    }\n  }\n  return counts;\n}\n\n// Concentrator bonus: rewards each port-to-port connection between a\n// Concentrator and an adjacent Energy Cells block, which the Concentrator\n// boosts in-game. Flat per connection — and, unlike the other amplifiers,\n// counted PER PORT rather than per component pair: with 8 outward ports the\n// Concentrator can legitimately land 2 separate connections against the\n// same Energy Cells block (e.g. both its E-side ports touching one 2x2\n// block), and each should score. Energy Cells' base ports are W/E only, but\n// rotated 90/270 degrees they become N/S — so all 8 of the Concentrator's\n// ports can connect given the right rotations, not just the 4 W/E-facing\n// ones. Optional — not required for layout validity, purely a scoring\n// incentive.\nconst CONCENTRATOR_TARGETS = new Set(['energy_cells']);\n\nfunction computeConcentratorBonus(placements) {\n  const portMap = new Map();\n  for (let i = 0; i < placements.length; i++) {\n    const p = placements[i];\n    if (p.componentId !== 'concentrator' && !CONCENTRATOR_TARGETS.has(p.componentId)) continue;\n    for (const { cell, side } of (p.rotatedPorts || [])) {\n      const key = `${p.row + cell[0]},${p.col + cell[1]},${side}`;\n      if (!portMap.has(key)) portMap.set(key, []);\n      portMap.get(key).push(i);\n    }\n  }\n\n  let bonus = 0;\n  const counted = new Set();\n  for (let i = 0; i < placements.length; i++) {\n    const p = placements[i];\n    if (p.componentId !== 'concentrator') continue;\n    for (const { cell, side } of (p.rotatedPorts || [])) {\n      const gr = p.row + cell[0], gc = p.col + cell[1];\n      const d = SIDE_DELTA[side];\n      const adjKey = `${gr + d.dr},${gc + d.dc},${OPPOSITE[side]}`;\n      if (!portMap.has(adjKey)) continue;\n      for (const j of portMap.get(adjKey)) {\n        if (!CONCENTRATOR_TARGETS.has(placements[j].componentId)) continue;\n        // Keyed by (i,j) only, like the other amplifier-family bonuses: a\n        // block that touches the Concentrator via 2 of its own ports still\n        // counts once. Rewards the number of DISTINCT connected blocks, not\n        // port-pairs — otherwise 4 double-porting blocks (8 port-pairs) tie\n        // 6 single-porting ones (6 port-pairs) instead of losing to them.\n        const pairKey = `${i},${j}`;\n        if (counted.has(pairKey)) continue;\n        counted.add(pairKey);\n        bonus += scoreWeights.concentrator;\n      }\n    }\n  }\n  return bonus;\n}\n\n// Aesthetic bonus: same-type components placed next to each other score +100\n// per pair; +200 if they are also port-to-port connected.\n// Spinners, Repeaters and wires are excluded — their adjacency rules are\n// governed by the working-set logic, not by aesthetics.\nconst CLUSTER_EXCLUDED  = new Set(['spinner', 'repeater_2s', 'repeater_4s', 'wire']);\n\nfunction computeClusterBonus(placements) {\n  // Cell → placement index map for eligible components.\n  const cellMap = new Map();\n  for (let i = 0; i < placements.length; i++) {\n    const p = placements[i];\n    if (CLUSTER_EXCLUDED.has(p.componentId)) continue;\n    for (const [r, c] of (p.rotatedShape || [])) {\n      cellMap.set(`${p.row + r},${p.col + c}`, i);\n    }\n  }\n\n  // Port-to-port connected pairs (normalised i < j).\n  const portConnected = new Set();\n  const portMap = new Map();\n  for (let i = 0; i < placements.length; i++) {\n    const p = placements[i];\n    if (CLUSTER_EXCLUDED.has(p.componentId)) continue;\n    for (const { cell, side } of (p.rotatedPorts || [])) {\n      const key = `${p.row + cell[0]},${p.col + cell[1]},${side}`;\n      if (!portMap.has(key)) portMap.set(key, []);\n      portMap.get(key).push(i);\n    }\n  }\n  for (let i = 0; i < placements.length; i++) {\n    const p = placements[i];\n    if (CLUSTER_EXCLUDED.has(p.componentId)) continue;\n    for (const { cell, side } of (p.rotatedPorts || [])) {\n      const gr = p.row + cell[0], gc = p.col + cell[1];\n      const d = SIDE_DELTA[side];\n      const adjKey = `${gr + d.dr},${gc + d.dc},${OPPOSITE[side]}`;\n      if (!portMap.has(adjKey)) continue;\n      for (const j of portMap.get(adjKey)) {\n        if (j > i) portConnected.add(`${i},${j}`);\n      }\n    }\n  }\n\n  // Sum bonus for each unique same-type cell-adjacent pair.\n  const counted = new Set();\n  let bonus = 0;\n  const DIRS = [[-1, 0], [1, 0], [0, -1], [0, 1]];\n  for (let i = 0; i < placements.length; i++) {\n    const p = placements[i];\n    if (CLUSTER_EXCLUDED.has(p.componentId)) continue;\n    for (const [r, c] of (p.rotatedShape || [])) {\n      for (const [dr, dc] of DIRS) {\n        const j = cellMap.get(`${p.row + r + dr},${p.col + c + dc}`);\n        if (j === undefined || j === i) continue;\n        if (placements[j].componentId !== p.componentId) continue;\n        const pairKey = i < j ? `${i},${j}` : `${j},${i}`;\n        if (counted.has(pairKey)) continue;\n        counted.add(pairKey);\n        bonus += portConnected.has(i < j ? `${i},${j}` : `${j},${i}`)\n          ? scoreWeights.cluster * 2\n          : scoreWeights.cluster;\n      }\n    }\n  }\n  return bonus;\n}\n\n// Final layout score — combines ten signals (thirteen weights — the Energy\n// Amplifier bonus alone splits into four) into one number that SA and the\n// synchronous greedy share. Higher is better. The components, in rough\n// magnitude order from largest to smallest at default weights:\n//   workingSet.size * weights.workingSet   — a working Spinner is the most valuable atom\n//   batteryAmpBonus                        — weights.batteryAmplifier per Battery Amplifier <->\n//                                           battery port connection, MULTIPLIED by that battery's\n//                                           cell count; see computeBatteryAmplifierBonus\n//   energyAmpBonus                         — weights.energyAmpBioGen/EnergyCells/Spinner/Pulser\n//                                           per Energy Amplifier <-> producer port connection, one\n//                                           weight per target type; see computeEnergyAmplifierBonus\n//   amplifierBonus                         — weights.amplifier per Power Amplifier <->\n//                                           Harvester/Salvager port connection; see computeAmplifierBonus\n//   concentratorBonus                      — weights.concentrator per Concentrator <-> Energy\n//                                           Cells port connection; see computeConcentratorBonus\n//   blockBonus.free * weights.freeBlock    — accessible open rectangles, escalates with area\n//   blockBonus.bus  * weights.busAccess    — same rectangles, EXTRA reward for touching the\n//                                           W/S bus directly (no wire needed there); independent\n//                                           of freeBlock so bus proximity can be tuned separately\n//   wires * weights.wirePenalty            — penalty: every auto-routed wire costs score\n//   quality * weights.quality              — fine-grained connectivity of remaining free cells\n//   clusterBonus                           — aesthetic: same-type neighbours, weights.cluster\n//                                           per pair (x2 if port-connected); see computeClusterBonus\n// Weights are player-tunable via Settings — see setScoreWeights above.\nfunction scoreLayout(placements, grid) {\n  const wires            = placements.filter(p => p.componentId === 'wire').length;\n  const quality          = computeFreeSpaceQuality(null, 0, 0, placements, grid.rows, grid.cols);\n  const workingSet       = computeWorkingSet(placements);\n  const blockBonus       = computeFreeBlockBonus(placements, grid.rows, grid.cols);\n  const amplifierBonus   = computeAmplifierBonus(placements);\n  const batteryAmpBonus  = computeBatteryAmplifierBonus(placements);\n  const energyAmpCounts  = computeEnergyAmplifierBonus(placements);\n  const energyAmpBonus   = energyAmpCounts.bioGen * scoreWeights.energyAmpBioGen\n                          + energyAmpCounts.energyCells * scoreWeights.energyAmpEnergyCells\n                          + energyAmpCounts.spinner * scoreWeights.energyAmpSpinner\n                          + energyAmpCounts.pulser * scoreWeights.energyAmpPulser;\n  const concentratorBonus = computeConcentratorBonus(placements);\n  const clusterBonus     = computeClusterBonus(placements);\n  return quality * scoreWeights.quality\n       - wires * scoreWeights.wirePenalty\n       + workingSet.size * scoreWeights.workingSet\n       + blockBonus.free * scoreWeights.freeBlock\n       + blockBonus.bus * scoreWeights.busAccess\n       + amplifierBonus\n       + batteryAmpBonus\n       + energyAmpBonus\n       + concentratorBonus\n       + clusterBonus;\n}\n\n\n// --- src/optimizer/validate.js ---\n// src/optimizer/validate.js — Layout validation and wire-bridging.\n// Shared by main thread and worker. Reads `componentLib` as a global\n// (defined in app.js or set on worker init).\n\n// Returns true if layout is fully valid:\n//   - every energy component is powered (connected to bus/powered chain)\n//   - every Spinner has required Repeaters adjacent (only when Repeaters exist)\n//   - every Repeater connects (port-match) to at least one Spinner OR Pulser\n//   - Pulsers do not require Repeaters\n//   - every Biocell/Disposable Biocell is port-adjacent to a Bio Generator\n//     (any tier) — they have normal electrical ports, but only function\n//     when plugged directly into one\nconst BIOCELL_IDS = new Set(['biocell', 'disposable_biocell']);\nconst BIO_GENERATOR_IDS = new Set(['bio_generator', 'bio_generator_ii']);\n\n// Upgrader: each of its (up to 2) ports is either PINNED to a specific\n// OTHER placement instance (by `pinTag`, assigned only via direct user\n// action — see _repinUpgrader in app.js, never by SA/RE-OPTIMIZE) or FREE.\n// A pinned port must stay port-adjacent to that exact instance across any\n// layout change, even after rotation/relocation. A free port must NOT pick\n// up an unintended connection to any other real component — SA/RE-OPTIMIZE\n// may only relay power to it via a wire there, never silently \"upgrade\" a\n// component the user didn't choose.\n//\n// Shared core: does SOME injective assignment of `ports` to `targetIdxs`\n// (placement indices, in order) exist such that each assigned port is\n// port-adjacent to its target, and every unassigned port touches no OTHER\n// real (non-wire) component? Used both for an already-placed Upgrader\n// (isLayoutValid, via _upgraderPinsOk below) and for a CANDIDATE position\n// being evaluated before commit (findBestPlacement in optimizer.js, which\n// passes `excludeSelf: null` since the candidate isn't in `placements` yet).\nfunction _upgraderPortAssignmentOk(ports, row, col, placements, targetIdxs, excludeSelf) {\n  if (targetIdxs.length > ports.length) return false; // can't pin more targets than ports\n\n  function adjCell(port) {\n    const gr = row + port.cell[0], gc = col + port.cell[1];\n    const d = SIDE_DELTA[port.side];\n    return { ar: gr + d.dr, ac: gc + d.dc };\n  }\n  function portTouchesPlacement(port, other) {\n    const { ar, ac } = adjCell(port);\n    return (other.rotatedPorts || []).some(tp =>\n      other.row + tp.cell[0] === ar && other.col + tp.cell[1] === ac && tp.side === OPPOSITE[port.side]\n    );\n  }\n  function portTouchesAnyOther(port) {\n    const { ar, ac } = adjCell(port);\n    return placements.some(other =>\n      other !== excludeSelf && other.componentId !== 'wire' &&\n      (other.rotatedPorts || []).some(tp =>\n        other.row + tp.cell[0] === ar && other.col + tp.cell[1] === ac && tp.side === OPPOSITE[port.side]\n      )\n    );\n  }\n\n  // Brute-force permutations of port indices assigned to targetIdxs, in\n  // order — at most 2 ports, so at most 2 permutations to try.\n  function permutations(arr) {\n    if (arr.length <= 1) return [arr];\n    const out = [];\n    arr.forEach((v, i) => {\n      const rest = [...arr.slice(0, i), ...arr.slice(i + 1)];\n      permutations(rest).forEach(p2 => out.push([v, ...p2]));\n    });\n    return out;\n  }\n\n  const portIdxs = ports.map((_, i) => i);\n  for (const perm of permutations(portIdxs)) {\n    let ok = true;\n    for (let t = 0; t < targetIdxs.length && ok; t++) {\n      if (!portTouchesPlacement(ports[perm[t]], placements[targetIdxs[t]])) ok = false;\n    }\n    for (let k = targetIdxs.length; k < perm.length && ok; k++) {\n      if (portTouchesAnyOther(ports[perm[k]])) ok = false;\n    }\n    if (ok) return true;\n  }\n  return false;\n}\n\nfunction _upgraderPinsOk(p, placements) {\n  const tags = p.pinnedTags || [];\n  const targetIdxs = tags\n    .map(tag => placements.findIndex(pp => pp.pinTag === tag))\n    .filter(idx => idx !== -1); // missing target = that pin was lost, silently dropped\n  return _upgraderPortAssignmentOk(p.rotatedPorts || [], p.row, p.col, placements, targetIdxs, p);\n}\n\nfunction isLayoutValid(placements, grid) {\n  const poweredSet  = computePoweredSet(placements, grid.rows, grid.cols);\n  const workingSet  = computeWorkingSet(placements);\n  const hasRepeaters = placements.some(p =>\n    p.componentId === 'repeater_4s' || p.componentId === 'repeater_2s'\n  );\n  const hasBiocells = placements.some(p => BIOCELL_IDS.has(p.componentId));\n\n  // Pre-build set of Spinner+Pulser port keys for Repeater \"useful-target\" check\n  let targetPortKeys = null;\n  if (hasRepeaters) {\n    targetPortKeys = new Set();\n    for (const p of placements) {\n      if (p.componentId !== 'spinner' && p.componentId !== 'pulser') continue;\n      for (const port of (p.rotatedPorts || [])) {\n        targetPortKeys.add(`${p.row+port.cell[0]},${p.col+port.cell[1]},${port.side}`);\n      }\n    }\n  }\n\n  // Pre-build set of Bio Generator port keys for the Biocell \"must be\n  // plugged into a generator\" check\n  let bioGenPortKeys = null;\n  if (hasBiocells) {\n    bioGenPortKeys = new Set();\n    for (const p of placements) {\n      if (!BIO_GENERATOR_IDS.has(p.componentId)) continue;\n      for (const port of (p.rotatedPorts || [])) {\n        bioGenPortKeys.add(`${p.row+port.cell[0]},${p.col+port.cell[1]},${port.side}`);\n      }\n    }\n  }\n\n  for (let i = 0; i < placements.length; i++) {\n    const p = placements[i];\n    if (p.componentId === 'wire') continue;\n    const def = componentLib.find(d => d.id === p.componentId);\n    if (!def) continue;\n    // Upgrader with no active pin needs no power of its own (see\n    // _upgraderPinsOk above) — everyone else, and a pinned Upgrader, keep\n    // the normal \"must reach the bus\" requirement.\n    const isFreeUpgrader = p.componentId === 'upgrader' && (!p.pinnedTags || p.pinnedTags.length === 0);\n    if (def.energyPorts.length > 0 && !isFreeUpgrader && !poweredSet.has(i)) return false;\n    if (p.componentId === 'upgrader' && !_upgraderPinsOk(p, placements)) return false;\n    if (p.componentId === 'spinner' && hasRepeaters && !workingSet.has(i)) return false;\n    if (p.componentId === 'repeater_2s' || p.componentId === 'repeater_4s') {\n      let connected = false;\n      for (const port of (p.rotatedPorts || [])) {\n        const gr = p.row + port.cell[0], gc = p.col + port.cell[1];\n        const d = SIDE_DELTA[port.side];\n        const adjKey = `${gr + d.dr},${gc + d.dc},${OPPOSITE[port.side]}`;\n        if (targetPortKeys.has(adjKey)) { connected = true; break; }\n      }\n      if (!connected) return false;\n    }\n    if (BIOCELL_IDS.has(p.componentId)) {\n      let connected = false;\n      for (const port of (p.rotatedPorts || [])) {\n        const gr = p.row + port.cell[0], gc = p.col + port.cell[1];\n        const d = SIDE_DELTA[port.side];\n        const adjKey = `${gr + d.dr},${gc + d.dc},${OPPOSITE[port.side]}`;\n        if (bioGenPortKeys.has(adjKey)) { connected = true; break; }\n      }\n      if (!connected) return false;\n    }\n  }\n  return true;\n}\n\n// For each unpowered energy component in a brute-force candidate layout, tries\n// to find a wire path connecting it to the bus or an already-powered component.\n// Returns the layout augmented with wires, or null if any component can't be\n// connected.\nfunction tryAddWires(placements, grid) {\n  const wireDef = componentLib.find(d => d.id === 'wire');\n  if (!wireDef) return null;\n\n  // Work on a copy so we don't mutate the generator's array\n  let current = placements.map((p, i) => ({ ...p, id: i + 1 }));\n\n  // Each iteration powers one more component; loop until all are powered or we give up\n  const maxIter = placements.filter(p => {\n    const def = componentLib.find(d => d.id === p.componentId);\n    return def && def.energyPorts.length > 0;\n  }).length + 1;\n\n  for (let iter = 0; iter < maxIter; iter++) {\n    const poweredSet = computePoweredSet(current, grid.rows, grid.cols);\n    const unpowered = [];\n\n    for (let i = 0; i < current.length; i++) {\n      const p = current[i];\n      if (p.componentId === 'wire') continue;\n      const def = componentLib.find(d => d.id === p.componentId);\n      if (!def || def.energyPorts.length === 0) continue;\n      if (p.componentId === 'upgrader' && (!p.pinnedTags || p.pinnedTags.length === 0)) continue; // free Upgrader: no power needed\n      if (poweredSet.has(i)) continue;\n      unpowered.push(p);\n    }\n\n    if (unpowered.length === 0) return current;\n\n    // Try every still-unpowered component this pass, not just the first —\n    // one placement's own port-adjacent cells may all be boxed in (no free\n    // cell to drop a wire on) while it's still directly port-connected to\n    // ANOTHER unpowered component that DOES have a free exit. Wiring that\n    // other one first powers both via the direct port link on the next\n    // pass, with no wire needed for the boxed-in one at all. Bailing out on\n    // the first placement's failure (old behaviour) missed exactly this case.\n    let wiredAny = false;\n    for (const p of unpowered) {\n      const path = findWirePath(p.rotatedShape, p.rotatedPorts, p.row, p.col, { grid, placements: current });\n      if (!path || path.length === 0) continue;\n\n      path.forEach(([r, c]) => {\n        current.push({\n          id: current.length + 1,\n          componentId: 'wire',\n          row: r, col: c, rotation: 0,\n          rotatedShape: [[0, 0]],\n          rotatedPorts: wireDef.energyPorts.map(ep => ({ cell: [...ep.cell], side: ep.side })),\n          rotatedPeripheral: null,\n          autoPlaced: true\n        });\n      });\n      wiredAny = true;\n      break;\n    }\n\n    // Nobody in this pass could be wired — genuinely stuck, not just a\n    // traversal-order artifact.\n    if (!wiredAny) return null;\n  }\n\n  return null;\n}\n\n\n// --- src/sa/shell.js ---\n// src/sa/shell.js — Shell packing heuristic.\n// Idea: bus is on left (col=0, W edge) and bottom (row=R-1, S edge).\n// The TOP and RIGHT edges are \"bus-free\" — components placed there are\n// farthest from the bus and have the worst wire-routing cost.\n//\n// Strategy: greedily pack the largest components into the top-right corner\n// with NO gaps between them. This creates a tight \"shell\" along the bus-free\n// edges, leaving the bus-near interior for components with shorter wire runs.\n//\n// Bonus: components packed against the N/E edges can use their ports on those\n// sides without wires (the edge is the same as \"no neighbour\"), reducing wire\n// count by ~1 per edge-side port.\n//\n// Returns: { shellPlacements: [...], remaining: [...] }\n//   shellPlacements — components placed in the shell (with row/col/rotation)\n//   remaining — IDs that didn't fit in the shell (for SA to handle)\n\nfunction packShell(componentIds, grid) {\n  const R = grid.rows, C = grid.cols;\n\n  // Sort by shape size descending — largest goes first (hardest to fit later)\n  const order = [...componentIds].sort((a, b) => {\n    const da = componentLib.find(d => d.id === a);\n    const db = componentLib.find(d => d.id === b);\n    return (db?.shape.length || 0) - (da?.shape.length || 0);\n  });\n\n  const occupied = new Set();\n  const shellPlacements = [];\n  const remaining = [];\n\n  for (const id of order) {\n    const def = componentLib.find(d => d.id === id);\n    if (!def) { remaining.push(id); continue; }\n    // Skip clusters from shell packing — clusters have W/E (or N/S) ports that\n    // need bus access, not edge placement. Let greedy fill them via\n    // findBestPlacement, which scores energy-port-to-bus connections.\n    if (def._isCluster) { remaining.push(id); continue; }\n\n    let best = null;\n    let bestScore = -Infinity;\n\n    for (const deg of getUniqueDegs(def)) {\n      const { shape, energyPorts } = rotateComponent(def, deg);\n      const bounds = getBounds(shape);\n      if (bounds.height > R || bounds.width > C) continue;\n      const rotPeri = buildRotatedPeri(def, deg);\n\n      // Try positions row-by-row from top, col scanned from RIGHT to LEFT.\n      // This biases packing into the top-right corner.\n      for (let row = 0; row <= R - bounds.height; row++) {\n        for (let col = C - bounds.width; col >= 0; col--) {\n          // Overlap check\n          let overlap = false;\n          for (const [r, c] of shape) {\n            if (occupied.has(`${row+r},${col+c}`)) { overlap = true; break; }\n          }\n          if (overlap) continue;\n\n          // Reserve peripheral (Biocell etc.) — cells must be free too\n          let periBlocked = false;\n          if (rotPeri) {\n            const d = SIDE_DELTA[rotPeri.port.side];\n            const baseR = row + rotPeri.port.cell[0] + d.dr;\n            const baseC = col + rotPeri.port.cell[1] + d.dc;\n            for (const [pr, pc] of rotPeri.shape) {\n              const rr = baseR + pr, cc = baseC + pc;\n              if (rr < 0 || rr >= R || cc < 0 || cc >= C) { periBlocked = true; break; }\n              if (occupied.has(`${rr},${cc}`)) { periBlocked = true; break; }\n            }\n          }\n          if (periBlocked) continue;\n\n          // Score: prefer top-right; reward NO gap with already placed cells\n          //   distFromCorner = row (0=top) + (C-1 - (col + width - 1))   (0=right)\n          //   adjacency bonus = how many shape cells touch occupied cells or N/E grid edges\n          const distFromCorner = row + (C - col - bounds.width);\n          let adjacency = 0;\n          for (const [r, c] of shape) {\n            const gr = row + r, gc = col + c;\n            // Check 4 neighbours; touching occupied or grid edge (N/E only) counts\n            if (gr === 0) adjacency++;                              // top edge\n            else if (occupied.has(`${gr-1},${gc}`)) adjacency++;\n            if (gc === C - 1) adjacency++;                          // right edge\n            else if (occupied.has(`${gr},${gc+1}`)) adjacency++;\n            if (gr > 0 && occupied.has(`${gr-1},${gc}`)) {/* already */}\n          }\n\n          // Port direction bonus: ports facing N or E (which become the OUTER side\n          // of the shell) are \"free\" — no wire needed. Ports facing S or W must be\n          // wire-connected through the interior.\n          let portBonus = 0;\n          for (const { cell, side } of energyPorts) {\n            const gr = row + cell[0], gc = col + cell[1];\n            if (side === 'N' && gr === 0) portBonus += 3;             // direct out, free\n            else if (side === 'E' && gc === C - 1) portBonus += 3;\n            else if (side === 'W' && gc === 0) portBonus += 10;       // ON the bus!\n            else if (side === 'S' && gr === R - 1) portBonus += 10;   // ON the bus!\n          }\n\n          // Compute score: lower distFromCorner is better; adjacency+ports add bonus\n          const score = -distFromCorner * 100 + adjacency * 10 + portBonus * 20;\n\n          if (score > bestScore) {\n            bestScore = score;\n            best = { row, col, deg, shape, energyPorts, rotPeri };\n          }\n        }\n      }\n    }\n\n    if (best) {\n      shellPlacements.push({\n        componentId: id,\n        row: best.row, col: best.col, rotation: best.deg,\n        rotatedShape: best.shape,\n        rotatedPorts: best.energyPorts,\n        rotatedPeripheral: best.rotPeri\n      });\n      for (const [r, c] of best.shape) occupied.add(`${best.row+r},${best.col+c}`);\n      // Mark peri cells as occupied too\n      if (best.rotPeri) {\n        const d = SIDE_DELTA[best.rotPeri.port.side];\n        const baseR = best.row + best.rotPeri.port.cell[0] + d.dr;\n        const baseC = best.col + best.rotPeri.port.cell[1] + d.dc;\n        for (const [pr, pc] of best.rotPeri.shape) {\n          occupied.add(`${baseR+pr},${baseC+pc}`);\n        }\n      }\n    } else {\n      remaining.push(id);\n    }\n  }\n\n  return { shellPlacements, remaining };\n}\n\n\n// --- src/sa/moves.js ---\n// src/sa/moves.js — Neighborhood move operators for Simulated Annealing.\n// All operators take the current non-wire placement list and return a NEW\n// list (or null if the move can't be applied). Wires are recomputed after\n// each accepted move via tryAddWires.\n\n// ── Helpers ─────────────────────────────────────────────────────────────────\n\n// Absolute grid cells occupied by a placement's peripheral (e.g. Biocell for\n// Bio Generator). Empty array if the component has no peripheral.\nfunction _saPeripheralCells(p) {\n  if (!p.rotatedPeripheral) return [];\n  const peri = p.rotatedPeripheral;\n  const d = SIDE_DELTA[peri.port.side];\n  const startR = p.row + peri.port.cell[0] + d.dr;\n  const startC = p.col + peri.port.cell[1] + d.dc;\n  return peri.shape.map(([r, c]) => [startR + r, startC + c]);\n}\n\nfunction _saHasOverlap(placements) {\n  const occupied = new Set();\n  for (const p of placements) {\n    if (!p.rotatedShape) continue;\n    for (const [r, c] of p.rotatedShape) {\n      const k = `${p.row+r},${p.col+c}`;\n      if (occupied.has(k)) return true;\n      occupied.add(k);\n    }\n    // Peripheral cells (e.g. Biocell) also reserve their space\n    for (const [gr, gc] of _saPeripheralCells(p)) {\n      const k = `${gr},${gc}`;\n      if (occupied.has(k)) return true;\n      occupied.add(k);\n    }\n  }\n  return false;\n}\n\nfunction _saFitsInGrid(p, grid) {\n  for (const [r, c] of p.rotatedShape) {\n    const gr = p.row + r, gc = p.col + c;\n    if (gr < 0 || gr >= grid.rows || gc < 0 || gc >= grid.cols) return false;\n  }\n  // Peripheral must also fit — otherwise auto-placed Biocell ends up off-grid\n  for (const [gr, gc] of _saPeripheralCells(p)) {\n    if (gr < 0 || gr >= grid.rows || gc < 0 || gc >= grid.cols) return false;\n  }\n  return true;\n}\n\n// `source`, if given, is the placement being replaced — its pinTag/pinnedTags\n// (Upgrader pin identity, see src/optimizer/validate.js) are carried over so\n// moves never silently strip a pin mid-search.\nfunction _saMakePlacement(id, row, col, rotation, source) {\n  const def = componentLib.find(d => d.id === id);\n  if (!def) return null;\n  const { shape, energyPorts } = rotateComponent(def, rotation);\n  return {\n    componentId: id, row, col, rotation,\n    rotatedShape: shape,\n    rotatedPorts: energyPorts,\n    rotatedPeripheral: buildRotatedPeri(def, rotation),\n    pinTag: source && source.pinTag, pinnedTags: source && source.pinnedTags\n  };\n}\n\nfunction _saRandomInt(n) { return Math.floor(Math.random() * n); }\n\n// ── Move operators ─────────────────────────────────────────────────────────\n\n// SWAP — exchange positions of two components, keeping each one's rotation.\nfunction saSwapMove(placements, grid) {\n  if (placements.length < 2) return null;\n  const i = _saRandomInt(placements.length);\n  let j = _saRandomInt(placements.length);\n  while (j === i) j = _saRandomInt(placements.length);\n\n  const a = placements[i], b = placements[j];\n  const newA = _saMakePlacement(a.componentId, b.row, b.col, a.rotation, a);\n  const newB = _saMakePlacement(b.componentId, a.row, a.col, b.rotation, b);\n  if (!newA || !newB) return null;\n  if (!_saFitsInGrid(newA, grid) || !_saFitsInGrid(newB, grid)) return null;\n\n  const next = placements.slice();\n  next[i] = newA;\n  next[j] = newB;\n  if (_saHasOverlap(next)) return null;\n  return next;\n}\n\n// ROTATE — try the next geometrically distinct rotation of one component.\nfunction saRotateMove(placements, grid) {\n  if (placements.length === 0) return null;\n  const i = _saRandomInt(placements.length);\n  const target = placements[i];\n  const def = componentLib.find(d => d.id === target.componentId);\n  if (!def) return null;\n  const uniqueDegs = getUniqueDegs(def);\n  if (uniqueDegs.length < 2) return null;\n\n  const otherDegs = uniqueDegs.filter(d => d !== target.rotation);\n  const newRot = otherDegs[_saRandomInt(otherDegs.length)];\n  const replaced = _saMakePlacement(target.componentId, target.row, target.col, newRot, target);\n  if (!replaced || !_saFitsInGrid(replaced, grid)) return null;\n\n  const next = placements.slice();\n  next[i] = replaced;\n  if (_saHasOverlap(next)) return null;\n  return next;\n}\n\n// SHIFT — translate one component by 1 cell in a random direction.\nfunction saShiftMove(placements, grid) {\n  if (placements.length === 0) return null;\n  const i = _saRandomInt(placements.length);\n  const target = placements[i];\n  const deltas = [[-1,0],[1,0],[0,-1],[0,1]];\n  const [dr, dc] = deltas[_saRandomInt(4)];\n  const moved = _saMakePlacement(target.componentId, target.row + dr, target.col + dc, target.rotation, target);\n  if (!moved || !_saFitsInGrid(moved, grid)) return null;\n\n  const next = placements.slice();\n  next[i] = moved;\n  if (_saHasOverlap(next)) return null;\n  return next;\n}\n\n// RELOCATE — remove one component and re-insert at a random valid position with a random rotation.\nfunction saRelocateMove(placements, grid) {\n  if (placements.length === 0) return null;\n  const i = _saRandomInt(placements.length);\n  const target = placements[i];\n  const def = componentLib.find(d => d.id === target.componentId);\n  if (!def) return null;\n\n  // Build occupied set from all other placements (shape AND peripheral cells)\n  const others = placements.filter((_, idx) => idx !== i);\n  const occupied = new Set();\n  for (const p of others) {\n    for (const [r, c] of p.rotatedShape) occupied.add(`${p.row+r},${p.col+c}`);\n    for (const [gr, gc] of _saPeripheralCells(p)) occupied.add(`${gr},${gc}`);\n  }\n\n  const degs = getUniqueDegs(def);\n  // Up to N tries (random sampling)\n  for (let tries = 0; tries < 30; tries++) {\n    const deg = degs[_saRandomInt(degs.length)];\n    const { shape } = rotateComponent(def, deg);\n    const bounds = getBounds(shape);\n    if (bounds.height > grid.rows || bounds.width > grid.cols) continue;\n    const row = _saRandomInt(grid.rows - bounds.height + 1);\n    const col = _saRandomInt(grid.cols - bounds.width + 1);\n    let overlap = false;\n    for (const [r, c] of shape) {\n      if (occupied.has(`${row+r},${col+c}`)) { overlap = true; break; }\n    }\n    if (overlap) continue;\n    const replaced = _saMakePlacement(target.componentId, row, col, deg, target);\n    if (!replaced) continue;\n    // _saMakePlacement attaches rotatedPeripheral; verify peripheral fits in\n    // grid AND doesn't overlap any other placement's cells.\n    if (!_saFitsInGrid(replaced, grid)) continue;\n    let periOverlap = false;\n    for (const [gr, gc] of _saPeripheralCells(replaced)) {\n      if (occupied.has(`${gr},${gc}`)) { periOverlap = true; break; }\n    }\n    if (periOverlap) continue;\n    const next = placements.slice();\n    next[i] = replaced;\n    return next;\n  }\n  return null;\n}\n\n// ── Chain moves — connected groups as atomic units ──────────────────────────\n//\n// SA's per-component moves can drift a connected group apart one move at a\n// time, and re-assembling it requires a long chain of accepted moves at\n// decreasing T — expensive, and for a group that's already at (or near) its\n// best possible connectivity, pure waste: individual moves can only ever\n// break it, never improve on \"already maximal\". Chain moves treat a whole\n// group as a single object and translate or rotate it in one accepted step,\n// preserving every internal connection exactly. Three kinds of group feed\n// the same shared translate/rotate mechanism (_saFindAllGroups below):\n//   - Spinner/Repeater chains (_saFindChains) — the original use case.\n//   - Upgrader pin-groups (_saFindPinGroups) — an Upgrader + whichever\n//     instance(s) it's pinned to (pinTag/pinnedTags); explicit user intent,\n//     not adjacency-scanned, since the pin IS the source of truth.\n//   - Amplifier-family clusters (_saFindAmplifierGroups) — a Power/Battery/\n//     Energy Amplifier or Concentrator + its currently port-connected\n//     target(s); adjacency-scanned like chains, since which targets are\n//     connected changes as the layout does.\n// This is additive, not exclusive — every group member remains individually\n// movable by the other move types too (shift/rotate/swap/relocate don't\n// check group membership), so fine-tuning within a group is still possible.\n\nconst _CHAIN_IDS = new Set(['spinner', 'repeater_2s', 'repeater_4s']);\n\n// Build adjacency over port-touching Spinners and Repeaters; return list of\n// connected components, each as an array of placement indices.\nfunction _saFindChains(placements) {\n  const cellOwner = new Map();\n  placements.forEach((p, idx) => {\n    if (!_CHAIN_IDS.has(p.componentId)) return;\n    for (const [r, c] of p.rotatedShape) cellOwner.set(`${p.row + r},${p.col + c}`, idx);\n  });\n\n  const neighbors = new Map();\n  placements.forEach((p, idx) => {\n    if (!_CHAIN_IDS.has(p.componentId)) return;\n    if (!neighbors.has(idx)) neighbors.set(idx, new Set());\n    for (const port of (p.rotatedPorts || [])) {\n      const gr = p.row + port.cell[0];\n      const gc = p.col + port.cell[1];\n      const d = SIDE_DELTA[port.side];\n      const k = `${gr + d.dr},${gc + d.dc}`;\n      const adj = cellOwner.get(k);\n      if (adj !== undefined && adj !== idx) {\n        neighbors.get(idx).add(adj);\n        if (!neighbors.has(adj)) neighbors.set(adj, new Set());\n        neighbors.get(adj).add(idx);\n      }\n    }\n  });\n\n  const visited = new Set();\n  const chains = [];\n  for (const start of neighbors.keys()) {\n    if (visited.has(start)) continue;\n    const stack = [start];\n    const comp = [];\n    while (stack.length > 0) {\n      const j = stack.pop();\n      if (visited.has(j)) continue;\n      visited.add(j);\n      comp.push(j);\n      for (const n of (neighbors.get(j) || [])) if (!visited.has(n)) stack.push(n);\n    }\n    if (comp.length >= 2) chains.push(comp);\n  }\n  return chains;\n}\n\n// Upgrader + its pinned target(s) — identity-based (pinTag/pinnedTags), not\n// adjacency-scanned, since the pin is explicit user-set data (see\n// _repinUpgrader in app.js and _upgraderPinsOk in src/optimizer/validate.js).\nfunction _saFindPinGroups(placements) {\n  const byTag = new Map();\n  placements.forEach((p, i) => { if (p.pinTag != null) byTag.set(p.pinTag, i); });\n\n  const groups = [];\n  placements.forEach((p, i) => {\n    if (p.componentId !== 'upgrader' || !p.pinnedTags || p.pinnedTags.length === 0) return;\n    const group = [i];\n    for (const tag of p.pinnedTags) {\n      const idx = byTag.get(tag);\n      if (idx !== undefined && !group.includes(idx)) group.push(idx);\n    }\n    if (group.length >= 2) groups.push(group);\n  });\n  return groups;\n}\n\n// True if `targetId` is a valid connection target for amplifier `ampId` —\n// mirrors the pairing rules in computeXBonus (src/optimizer/score.js) and\n// getXConnectionBonus (optimizer.js). AMPLIFIER_TARGETS, _isBatteryTarget,\n// ENERGY_AMPLIFIER_TARGETS, CONCENTRATOR_TARGETS, AMPLIFIER_TYPE_IDS are all\n// defined once in score.js (loaded before this file).\nfunction _saIsAmplifierPair(ampId, targetId) {\n  if (ampId === 'power_amplifier')   return AMPLIFIER_TARGETS.has(targetId);\n  if (ampId === 'battery_amplifier') return _isBatteryTarget(targetId);\n  if (ampId === 'energy_amplifier')  return ENERGY_AMPLIFIER_TARGETS.has(targetId);\n  if (ampId === 'concentrator')      return CONCENTRATOR_TARGETS.has(targetId);\n  return false;\n}\n\n// Power/Battery/Energy Amplifier or Concentrator + whichever target(s) are\n// CURRENTLY port-connected to it — adjacency-scanned like chains, since\n// which targets are connected changes as the layout does (unlike Upgrader\n// pins, there's no fixed identity to track).\nfunction _saFindAmplifierGroups(placements) {\n  const cellOwner = new Map();\n  placements.forEach((p, idx) => {\n    for (const [r, c] of p.rotatedShape) cellOwner.set(`${p.row + r},${p.col + c}`, idx);\n  });\n\n  const neighbors = new Map();\n  placements.forEach((p, idx) => {\n    if (!AMPLIFIER_TYPE_IDS.has(p.componentId)) return; // scan FROM amplifiers only (asymmetric)\n    for (const port of (p.rotatedPorts || [])) {\n      const gr = p.row + port.cell[0], gc = p.col + port.cell[1];\n      const d = SIDE_DELTA[port.side];\n      const ar = gr + d.dr, ac = gc + d.dc;\n      const adj = cellOwner.get(`${ar},${ac}`);\n      if (adj === undefined || adj === idx) continue;\n      const other = placements[adj];\n      if (!_saIsAmplifierPair(p.componentId, other.componentId)) continue;\n      const matches = (other.rotatedPorts || []).some(op =>\n        other.row + op.cell[0] === ar && other.col + op.cell[1] === ac && op.side === OPPOSITE[port.side]\n      );\n      if (!matches) continue;\n      if (!neighbors.has(idx)) neighbors.set(idx, new Set());\n      if (!neighbors.has(adj)) neighbors.set(adj, new Set());\n      neighbors.get(idx).add(adj);\n      neighbors.get(adj).add(idx);\n    }\n  });\n\n  const visited = new Set();\n  const groups = [];\n  for (const start of neighbors.keys()) {\n    if (visited.has(start)) continue;\n    const stack = [start];\n    const comp = [];\n    while (stack.length > 0) {\n      const j = stack.pop();\n      if (visited.has(j)) continue;\n      visited.add(j);\n      comp.push(j);\n      for (const n of (neighbors.get(j) || [])) if (!visited.has(n)) stack.push(n);\n    }\n    if (comp.length >= 2) groups.push(comp);\n  }\n  return groups;\n}\n\n// All \"move together\" groups from every detector, concatenated — a single\n// random pick (in saChainTranslate/saChainRotate) covers all three kinds\n// with the one shared translate/rotate mechanism below.\nfunction _saFindAllGroups(placements) {\n  return [\n    ..._saFindChains(placements),\n    ..._saFindPinGroups(placements),\n    ..._saFindAmplifierGroups(placements)\n  ];\n}\n\n// Compute the chain's bounding box from its placements' shape cells.\nfunction _saChainBbox(placements, chain) {\n  let minR = Infinity, maxR = -Infinity, minC = Infinity, maxC = -Infinity;\n  for (const idx of chain) {\n    const p = placements[idx];\n    for (const [r, c] of p.rotatedShape) {\n      const gr = p.row + r, gc = p.col + c;\n      if (gr < minR) minR = gr;\n      if (gr > maxR) maxR = gr;\n      if (gc < minC) minC = gc;\n      if (gc > maxC) maxC = gc;\n    }\n  }\n  return { minR, maxR, minC, maxC };\n}\n\n// TRANSLATE — shift the entire group by (dr, dc).\nfunction saChainTranslate(placements, grid) {\n  const chains = _saFindAllGroups(placements);\n  if (chains.length === 0) return null;\n  const chain = chains[_saRandomInt(chains.length)];\n  const chainSet = new Set(chain);\n\n  // Try shifts of magnitudes 1..4 in random directions\n  const deltas = [];\n  for (let mag = 1; mag <= 4; mag++) {\n    deltas.push([-mag, 0], [mag, 0], [0, -mag], [0, mag]);\n  }\n  // Shuffle so the order of attempted directions is random per call\n  for (let i = deltas.length - 1; i > 0; i--) {\n    const j = _saRandomInt(i + 1);\n    [deltas[i], deltas[j]] = [deltas[j], deltas[i]];\n  }\n\n  for (const [dr, dc] of deltas) {\n    const next = placements.slice();\n    let ok = true;\n    for (const idx of chain) {\n      const p = placements[idx];\n      const moved = { ...p, row: p.row + dr, col: p.col + dc };\n      if (!_saFitsInGrid(moved, grid)) { ok = false; break; }\n      next[idx] = moved;\n    }\n    if (!ok) continue;\n    if (_saHasOverlap(next)) continue;\n    return next;\n  }\n  return null;\n}\n\n// ROTATE — rotate the entire group by 90/180/270 around its bbox top-left.\n// Each component's anchor and rotation update so the rotated-shape cells\n// match the cells produced by rotating the group as a unit.\nfunction saChainRotate(placements, grid) {\n  const chains = _saFindAllGroups(placements);\n  if (chains.length === 0) return null;\n  const chain = chains[_saRandomInt(chains.length)];\n  const { minR, maxR, minC, maxC } = _saChainBbox(placements, chain);\n\n  const angle = [90, 180, 270][_saRandomInt(3)];\n  // Rotation around bbox top-left so output stays in non-negative offsets.\n  // After the transform, we shift the result to keep the chain inside the grid.\n  const transform = (gr, gc) => {\n    if (angle === 90)  return [minR + (gc - minC),     minC + (maxR - gr)];\n    if (angle === 180) return [minR + (maxR - gr),     minC + (maxC - gc)];\n    return                  [minR + (maxC - gc),       minC + (gr - minR)];\n  };\n\n  const next = placements.slice();\n  for (const idx of chain) {\n    const p = placements[idx];\n    const def = componentLib.find(d => d.id === p.componentId);\n    if (!def) return null;\n    const transformed = p.rotatedShape.map(([r, c]) => transform(p.row + r, p.col + c));\n    const newAnchorR = Math.min(...transformed.map(([r]) => r));\n    const newAnchorC = Math.min(...transformed.map(([, c]) => c));\n    const newRot = (p.rotation + angle) % 360;\n    const rotated = rotateComponent(def, newRot);\n    const movedP = {\n      ...p,\n      row: newAnchorR,\n      col: newAnchorC,\n      rotation: newRot,\n      rotatedShape: rotated.shape,\n      rotatedPorts: rotated.energyPorts,\n      rotatedPeripheral: buildRotatedPeri(def, newRot)\n    };\n    if (!_saFitsInGrid(movedP, grid)) return null;\n    next[idx] = movedP;\n  }\n  if (_saHasOverlap(next)) return null;\n  return next;\n}\n\n// Per-worker move bias — settable global. Each worker sets its own profile\n// to encourage strategic diversity:\n//   - balanced  (default):  even mix of all moves\n//   - local:    high shift/rotate (fine-tune near current state)\n//   - rotate:   heavy rotate (explore orientations)\n//   - swap:     heavy swap (re-pair components)\n//   - jump:     heavy relocate (escape local minima)\nlet saMoveBias = { shift: 0.22, rotate: 0.27, swap: 0.27, relocate: 0.14, chain: 0.10 };\n\nfunction setSaMoveBias(profile) {\n  switch (profile) {\n    case 'local':   saMoveBias = { shift: 0.45, rotate: 0.27, swap: 0.13, relocate: 0.05, chain: 0.10 }; break;\n    case 'rotate':  saMoveBias = { shift: 0.13, rotate: 0.50, swap: 0.17, relocate: 0.10, chain: 0.10 }; break;\n    case 'swap':    saMoveBias = { shift: 0.13, rotate: 0.17, swap: 0.50, relocate: 0.10, chain: 0.10 }; break;\n    case 'jump':    saMoveBias = { shift: 0.07, rotate: 0.13, swap: 0.13, relocate: 0.47, chain: 0.20 }; break;\n    case 'balanced':\n    default:        saMoveBias = { shift: 0.22, rotate: 0.27, swap: 0.27, relocate: 0.14, chain: 0.10 }; break;\n  }\n}\n\n// Main move generator — picks a random operator with weighted probability.\nfunction saGenerateMove(placements, grid) {\n  const r = Math.random();\n  let cum = saMoveBias.shift;\n  if (r < cum) return saShiftMove(placements, grid);\n  cum += saMoveBias.rotate;\n  if (r < cum) return saRotateMove(placements, grid);\n  cum += saMoveBias.swap;\n  if (r < cum) return saSwapMove(placements, grid);\n  cum += saMoveBias.relocate;\n  if (r < cum) return saRelocateMove(placements, grid);\n  // Chain moves — half translate, half rotate\n  return Math.random() < 0.5 ? saChainTranslate(placements, grid) : saChainRotate(placements, grid);\n}\n\n\n// --- src/sa/clusters.js ---\n// src/sa/clusters.js — Spinner-Repeater cluster pre-baking.\n//\n// Spinner requires Repeater adjacency (Rep_2s on any side, OR Rep_4s on both).\n// One Repeater can serve up to two Spinners when placed between them, so\n// these constraints naturally tile into linear chains:\n//\n//   Pattern A (Rep_2s):  S - R2 - S - R2 - S - R2 - S - ...\n//     N spinners need (N-1) Rep_2s\n//\n//   Pattern B (Rep_4s):  R4 - S - R4 - S - R4 - S - R4 - ...\n//     M spinners need (M+1) Rep_4s\n//\n// Instead of letting the search optimize the constraint blindly, we synthesise\n// the longest possible chain as a single composite \"cluster component\" and\n// substitute it in nonWireIds. The search then treats the cluster as one\n// atomic placement — much smaller search space, every cluster placement is\n// guaranteed valid by construction.\n//\n// LIMITATION: this initial implementation only supports the canonical\n// horizontal orientation (rotation 0). Cluster can be placed but not rotated\n// 90/180/270 by the search. TODO: pre-rotate cluster variants.\n\n// Count S/R/R4 in a non-wire id list (others returned separately).\nfunction _saCountAvailable(nonWireIds) {\n  const counts = { spinner: 0, repeater_2s: 0, repeater_4s: 0 };\n  const others = [];\n  for (const id of nonWireIds) {\n    if (counts.hasOwnProperty(id)) counts[id]++;\n    else others.push(id);\n  }\n  return { counts, others };\n}\n\n// Enumerate ALL cluster def variants supported by the available components.\n// Lengths from minimum chain up to the largest possible chain given budget.\n// Called once at the start of the search; resulting defs are registered into\n// componentLib so the search has full freedom over which sizes to actually use.\nfunction enumerateAllClusterDefs(nonWireIds) {\n  const { counts } = _saCountAvailable(nonWireIds);\n  const defs = [];\n\n  // Pattern A — S-R2-S chain; needs 2+ spinners and 1+ rep_2s.\n  // Max chain length = min(spinners, rep_2s + 1)\n  if (counts.spinner >= 2 && counts.repeater_2s >= 1) {\n    const maxA = Math.min(counts.spinner, counts.repeater_2s + 1);\n    for (let n = 2; n <= maxA; n++) {\n      const def = buildClusterDef('A', n);\n      if (def) defs.push(def);\n    }\n  }\n  // Pattern B — R4-S-R4 chain; needs 1+ spinners and 2+ rep_4s.\n  if (counts.spinner >= 1 && counts.repeater_4s >= 2) {\n    const maxB = Math.min(counts.spinner, counts.repeater_4s - 1);\n    for (let m = 1; m <= maxB; m++) {\n      const def = buildClusterDef('B', m);\n      if (def) defs.push(def);\n    }\n  }\n  return defs;\n}\n\n// Enumerate all valid decompositions (ways to partition components into clusters).\n// Returns list of { clusters: [{pattern, spinners}, ...], remaining: {...} }.\n// Uses canonical ordering (cluster sizes non-decreasing) to avoid duplicates.\nfunction enumerateDecompositions(nonWireIds) {\n  const { counts } = _saCountAvailable(nonWireIds);\n  const results = [];\n\n  function recurseA(remS, remR2, current, minSize) {\n    // Record current state as a candidate (only if non-empty)\n    if (current.length > 0) results.push({ clusters: current.slice() });\n    const maxN = Math.min(remS, remR2 + 1);\n    for (let n = minSize; n <= maxN; n++) {\n      if (n - 1 > remR2) continue;\n      current.push({ pattern: 'A', spinners: n });\n      recurseA(remS - n, remR2 - (n - 1), current, n);\n      current.pop();\n    }\n  }\n  function recurseB(remS, remR4, current, minSize) {\n    if (current.length > 0) results.push({ clusters: current.slice() });\n    const maxM = Math.min(remS, remR4 - 1);\n    for (let m = minSize; m <= maxM; m++) {\n      if (m + 1 > remR4) continue;\n      current.push({ pattern: 'B', spinners: m });\n      recurseB(remS - m, remR4 - (m + 1), current, m);\n      current.pop();\n    }\n  }\n\n  if (counts.spinner >= 2 && counts.repeater_2s >= 1) {\n    recurseA(counts.spinner, counts.repeater_2s, [], 2);\n  }\n  if (counts.spinner >= 1 && counts.repeater_4s >= 2) {\n    recurseB(counts.spinner, counts.repeater_4s, [], 1);\n  }\n  return results;\n}\n\n// Score a decomposition for ranking: more clustered spinners = better.\nfunction _saScoreDecomposition(decomp) {\n  const totalS = decomp.clusters.reduce((s, c) => s + c.spinners, 0);\n  const totalR = decomp.clusters.reduce((s, c) => {\n    return s + (c.pattern === 'A' ? c.spinners - 1 : c.spinners + 1);\n  }, 0);\n  return totalS * 1000 - decomp.clusters.length * 10 + totalR;\n}\n\n// Pick a decomposition deterministically by workerId — workers get\n// different decompositions for structural diversity. Sorted by usage desc.\nfunction pickDecompositionForWorker(decompositions, workerId) {\n  if (decompositions.length === 0) return { clusters: [] };\n  const sorted = decompositions.slice().sort((a, b) => _saScoreDecomposition(b) - _saScoreDecomposition(a));\n  return sorted[workerId % sorted.length];\n}\n\n// Backward-compatible: greedy best decomposition (used when no workerId given)\nfunction detectClusterOpportunities(nonWireIds) {\n  const decomps = enumerateDecompositions(nonWireIds);\n  const picked = pickDecompositionForWorker(decomps, 0);\n  return picked;\n}\n\n// Build a synthetic component def for a cluster.\n// Internal placements use original-orientation coordinates (cluster rotation 0).\nfunction buildClusterDef(pattern, spinners) {\n  const internals = [];\n  const shapeCells = [];\n\n  if (pattern === 'A') {\n    // S(0) - R2(0) - S(0) - R2(0) - ... - S(0)\n    // Each Spinner: 3-row × 2-col block, port row at bottom (row 2)\n    // Each Rep_2s: 2-row × 1-col block at columns rows 1..2\n    // Total width: 3N - 1, total height: 3 (where N = spinners)\n    for (let i = 0; i < spinners; i++) {\n      const baseCol = i * 3;\n      // Spinner cells\n      for (let r = 0; r < 3; r++) for (let c = 0; c < 2; c++) shapeCells.push([r, baseCol + c]);\n      internals.push({ componentId: 'spinner', relRow: 0, relCol: baseCol, rotation: 0 });\n      // Rep_2s after each spinner except last\n      if (i < spinners - 1) {\n        const repCol = baseCol + 2;\n        shapeCells.push([1, repCol]);\n        shapeCells.push([2, repCol]);\n        internals.push({ componentId: 'repeater_2s', relRow: 1, relCol: repCol, rotation: 0 });\n      }\n    }\n    const width = 3 * spinners - 1;\n    return {\n      id: `cluster_A${spinners}`,\n      name: `Cluster A${spinners}`,\n      shape: shapeCells,\n      energyPorts: [\n        { cell: [2, 0], side: 'W' },           // leftmost Spinner's W (external)\n        { cell: [2, width - 1], side: 'E' }    // rightmost Spinner's E (external)\n      ],\n      peripheral: null,\n      color: '#80CBC4', bgColor: '#003830',\n      icon: '⛓',\n      description: `Spinner-Rep_2s chain of ${spinners} spinners + ${spinners-1} Rep_2s.`,\n      _internalPlacements: internals,\n      _isCluster: true\n    };\n  }\n\n  if (pattern === 'B') {\n    // R4(0) - S(0) - R4(0) - S(0) - ... - R4(0)\n    // M spinners + (M+1) rep_4s\n    // Width = 3*M + 1, height = 3\n    shapeCells.push([1, 0], [2, 0]);\n    internals.push({ componentId: 'repeater_4s', relRow: 1, relCol: 0, rotation: 0 });\n    for (let i = 0; i < spinners; i++) {\n      const sCol = 1 + i * 3;\n      for (let r = 0; r < 3; r++) for (let c = 0; c < 2; c++) shapeCells.push([r, sCol + c]);\n      internals.push({ componentId: 'spinner', relRow: 0, relCol: sCol, rotation: 0 });\n      const rCol = sCol + 2;\n      shapeCells.push([1, rCol], [2, rCol]);\n      internals.push({ componentId: 'repeater_4s', relRow: 1, relCol: rCol, rotation: 0 });\n    }\n    const width = 3 * spinners + 1;\n    return {\n      id: `cluster_B${spinners}`,\n      name: `Cluster B${spinners}`,\n      shape: shapeCells,\n      energyPorts: [\n        { cell: [2, 0], side: 'W' },           // leftmost Rep_4s W\n        { cell: [2, width - 1], side: 'E' }    // rightmost Rep_4s E\n      ],\n      peripheral: null,\n      color: '#80CBC4', bgColor: '#001a12',\n      icon: '⛓',\n      description: `Rep_4s-Spinner chain of ${spinners} spinners + ${spinners+1} Rep_4s.`,\n      _internalPlacements: internals,\n      _isCluster: true\n    };\n  }\n  return null;\n}\n\n// Pre-compute internal sub-placements for all 4 cluster rotations so\n// expandClusterPlacement can look them up directly without recomputing.\nfunction _precomputeRotationVariants(def) {\n  if (!def._internalPlacements) return;\n  const result = { 0: def._internalPlacements };\n  const maxR = Math.max(...def.shape.map(([r]) => r));\n  const maxC = Math.max(...def.shape.map(([, c]) => c));\n\n  for (const rot of [90, 180, 270]) {\n    // Rotated cluster shape to find normalization offset\n    const rotatedShape = def.shape.map(([r, c]) => rotateCoord(r, c, maxR, maxC, rot));\n    const offsetR = Math.min(...rotatedShape.map(([r]) => r));\n    const offsetC = Math.min(...rotatedShape.map(([, c]) => c));\n\n    const rotInternals = [];\n    for (const ip of def._internalPlacements) {\n      const subDef = componentLib.find(d => d.id === ip.componentId);\n      if (!subDef) continue;\n      // Sub-component shape in its own original rotation\n      const subShape = rotateComponent(subDef, ip.rotation).shape;\n      // Where its cells sit in the original (rotation 0) cluster\n      const subCellsInCluster = subShape.map(([sr, sc]) => [ip.relRow + sr, ip.relCol + sc]);\n      // Rotate each cell by cluster's rotation, then normalise\n      const rotatedSubCells = subCellsInCluster.map(([r, c]) => rotateCoord(r, c, maxR, maxC, rot));\n      const normalized = rotatedSubCells.map(([r, c]) => [r - offsetR, c - offsetC]);\n      const newRelRow = Math.min(...normalized.map(([r]) => r));\n      const newRelCol = Math.min(...normalized.map(([, c]) => c));\n      rotInternals.push({\n        componentId: ip.componentId,\n        relRow: newRelRow,\n        relCol: newRelCol,\n        rotation: (ip.rotation + rot) % 360,\n        pinTag: ip.pinTag, pinnedTags: ip.pinnedTags // must survive rotation variants too\n      });\n    }\n    result[rot] = rotInternals;\n  }\n  def._internalsByRotation = result;\n}\n\n// Register cluster defs into componentLib (idempotent). Precomputes all 4\n// rotation variants of internal placements so expansion works for any rotation.\nfunction registerClusterDefs(defs) {\n  for (const def of defs) {\n    if (!def) continue;\n    if (!componentLib.find(d => d.id === def.id)) {\n      componentLib.push(def);\n    }\n    _precomputeRotationVariants(def);\n    // Note: we DO NOT force [0] in _uniqueRotsCache anymore — all 4 rotations\n    // are valid placements for the cluster, and expansion handles them.\n  }\n}\n\n// Substitute cluster IDs into a nonWireIds list — replaces the constituent\n// components with cluster placement tokens. Decomposition is { clusters: [...] }.\nfunction substituteClusterIds(nonWireIds, decomposition) {\n  const result = [];\n  const absorbed = { spinner: 0, repeater_2s: 0, repeater_4s: 0 };\n  for (const c of decomposition.clusters) {\n    if (c.pattern === 'A') {\n      absorbed.spinner += c.spinners;\n      absorbed.repeater_2s += (c.spinners - 1);\n    } else if (c.pattern === 'B') {\n      absorbed.spinner += c.spinners;\n      absorbed.repeater_4s += (c.spinners + 1);\n    }\n    result.push(`cluster_${c.pattern}${c.spinners}`);\n  }\n  for (const id of nonWireIds) {\n    if (absorbed[id] > 0) { absorbed[id]--; continue; }\n    result.push(id);\n  }\n  return result;\n}\n\n// Expand a cluster placement back into individual component placements.\n// Uses precomputed _internalsByRotation to handle any cluster rotation (0/90/180/270).\nfunction expandClusterPlacement(clusterPlacement, clusterDef) {\n  const rot = clusterPlacement.rotation || 0;\n  const internals = (clusterDef._internalsByRotation && clusterDef._internalsByRotation[rot])\n    ? clusterDef._internalsByRotation[rot]\n    : clusterDef._internalPlacements;\n  const out = [];\n  for (const ip of internals) {\n    const subDef = componentLib.find(d => d.id === ip.componentId);\n    if (!subDef) continue;\n    const rotated = rotateComponent(subDef, ip.rotation);\n    out.push({\n      componentId: ip.componentId,\n      row: clusterPlacement.row + ip.relRow,\n      col: clusterPlacement.col + ip.relCol,\n      rotation: ip.rotation,\n      rotatedShape: rotated.shape,\n      rotatedPorts: rotated.energyPorts,\n      rotatedPeripheral: buildRotatedPeri(subDef, ip.rotation),\n      pinTag: ip.pinTag, pinnedTags: ip.pinnedTags // survives the merge/expand round-trip — see buildMergedBlockDef\n    });\n  }\n  return out;\n}\n\n// Walk a placement list and expand any cluster placements into individuals.\n// Used at SA cost-evaluation time and on result reporting.\nfunction expandClustersInPlacements(placements) {\n  const out = [];\n  for (const p of placements) {\n    const def = componentLib.find(d => d.id === p.componentId);\n    if (def && def._isCluster) {\n      out.push(...expandClusterPlacement(p, def));\n    } else {\n      out.push(p);\n    }\n  }\n  return out;\n}\n\n// ── Merged blocks — an EXISTING connected group frozen into one rigid atom ──\n//\n// buildClusterDef above builds a fixed TEMPLATE (a canonical S-R pattern)\n// used at seed-construction time, before anything is placed. This is the\n// opposite direction: given placements that are ALREADY positioned (the\n// user's own layout), derive a composite shape/ports from their CURRENT\n// relative arrangement and register it as a cluster-like def — same\n// _isCluster/_internalPlacements contract, so expandClustersInPlacements\n// and _precomputeRotationVariants (free 0/90/180/270 rotation) work\n// unchanged. Once merged, SA's move set (shift/rotate/swap/relocate — see\n// src/sa/moves.js) sees ONE placement and can only move/rotate the whole\n// thing; no move type can single out one member, so the group's internal\n// connections can never be broken by the search. Members keep whatever\n// EXTERNAL (non-internal) ports they had — an unrelated, still-individual\n// component can still connect to those from outside; only the merged\n// members themselves are locked relative to each other.\nlet _mergedBlockCounter = 0;\n\nfunction buildMergedBlockDef(placements, groupIndices) {\n  let minR = Infinity, minC = Infinity;\n  for (const idx of groupIndices) {\n    const p = placements[idx];\n    for (const [r, c] of p.rotatedShape) {\n      minR = Math.min(minR, p.row + r);\n      minC = Math.min(minC, p.col + c);\n    }\n  }\n\n  const memberCells = new Set();\n  for (const idx of groupIndices) {\n    const p = placements[idx];\n    for (const [r, c] of p.rotatedShape) memberCells.add(`${p.row + r},${p.col + c}`);\n  }\n\n  const shapeCells = [];\n  const internals = [];\n  const energyPorts = [];\n  for (const idx of groupIndices) {\n    const p = placements[idx];\n    for (const [r, c] of p.rotatedShape) shapeCells.push([p.row + r - minR, p.col + c - minC]);\n    internals.push({\n      componentId: p.componentId, relRow: p.row - minR, relCol: p.col - minC, rotation: p.rotation || 0,\n      pinTag: p.pinTag, pinnedTags: p.pinnedTags // must survive the merge/expand round-trip — see _upgraderPinsOk\n    });\n\n    // External ports only — a port touching ANOTHER member of this same\n    // group is internal (already satisfied by the merge), not exposed.\n    for (const port of (p.rotatedPorts || [])) {\n      const gr = p.row + port.cell[0], gc = p.col + port.cell[1];\n      const d = SIDE_DELTA[port.side];\n      const ar = gr + d.dr, ac = gc + d.dc;\n      if (memberCells.has(`${ar},${ac}`)) continue;\n      energyPorts.push({ cell: [gr - minR, gc - minC], side: port.side });\n    }\n  }\n\n  _mergedBlockCounter++;\n  const def = {\n    id: `merged_block_${_mergedBlockCounter}`,\n    name: 'Merged block',\n    shape: shapeCells,\n    energyPorts,\n    peripheral: null,\n    color: '#B39DDB', bgColor: '#1a1030',\n    icon: '⬢',\n    description: `Merged block of ${groupIndices.length} components — moves/rotates only as a whole.`,\n    _internalPlacements: internals,\n    _isCluster: true\n  };\n  return { def, anchorRow: minR, anchorCol: minC };\n}\n\n// Detect groups worth freezing into merged blocks — Upgrader pin-groups\n// (always, a pin is inviolable by design) and amplifier-family clusters\n// (Power/Battery/Energy Amplifier or Concentrator + currently-connected\n// target(s) — see _saFindPinGroups / _saFindAmplifierGroups in\n// src/sa/moves.js, loaded before this file) — and replace each with one\n// merged block placement, registered into componentLib. Used only for a SA\n// run seeded from the user's own layout (see sa-worker.js): the fallback\n// from-scratch greedy path has no existing arrangement to derive blocks\n// from. Returns a NEW placements array; components outside any detected\n// group pass through unchanged.\nfunction mergeConnectedGroupsIntoBlocks(placements) {\n  const groups = [..._saFindPinGroups(placements), ..._saFindAmplifierGroups(placements)];\n  if (groups.length === 0) return placements;\n\n  const merged = new Set();\n  const result = [];\n  for (const group of groups) {\n    if (group.some(idx => merged.has(idx))) continue; // overlapping group (shouldn't normally happen) — first one wins\n    group.forEach(idx => merged.add(idx));\n    const { def, anchorRow, anchorCol } = buildMergedBlockDef(placements, group);\n    registerClusterDefs([def]);\n    result.push({\n      componentId: def.id, row: anchorRow, col: anchorCol, rotation: 0,\n      rotatedShape: def.shape.map(c => [...c]),\n      rotatedPorts: def.energyPorts.map(p => ({ cell: [...p.cell], side: p.side })),\n      rotatedPeripheral: null\n    });\n  }\n  placements.forEach((p, idx) => { if (!merged.has(idx)) result.push(p); });\n  return result;\n}\n\n\n// --- src/sa/greedy.js ---\n// src/sa/greedy.js — Build the SA initial state via greedy placement.\n//\n// The user's current grid state may be dense and invalid (Re-Optimize gone wrong\n// or hand-placed). Using it directly as SA seed often leaves SA stuck — moves\n// can't break overlaps and dense grids reject everything. So instead we\n// reconstruct a valid layout from scratch using the same greedy algorithm as\n// the RE-OPTIMIZE button: findBestPlacement with energy-aware scoring.\n//\n// Returns non-wire placements only (SA operates on those; wires are computed\n// at cost-evaluation time via tryAddWires).\n\nconst _SA_REP_IDS = new Set(['repeater_2s', 'repeater_4s']);\n\nfunction _saComponentOrder(ids) {\n  // Biocell/Disposable Biocell (BIOCELL_IDS, src/optimizer/validate.js) go\n  // after \"others\" (so their Bio Generator is already placed) but BEFORE\n  // Repeaters/Spinners — same most-constrained-first reasoning as\n  // ensureComponentOrder in app.js (RE-OPTIMIZE): an unrelated Repeater\n  // placed first can grab a Biocell's one valid cell, starving it into the\n  // geometry-only fallback. Biocells never compete with Repeater/Spinner\n  // for cells, so placing them earlier is free.\n  const spinnerSet = new Set(['spinner', 'pulser']);\n\n  const bioOnly    = ids.filter(id => BIOCELL_IDS.has(id));\n  const reps       = ids.filter(id => _SA_REP_IDS.has(id));\n  const spinners   = ids.filter(id => spinnerSet.has(id));\n  const isOther    = id => !BIOCELL_IDS.has(id) && !_SA_REP_IDS.has(id) && !spinnerSet.has(id);\n  // Amplifier-family components (Power/Battery/Energy Amplifier, Concentrator)\n  // go before their targets — same reasoning as bioOnly above.\n  const amplifiers = ids.filter(id => isOther(id) && AMPLIFIER_TYPE_IDS.has(id));\n  const others      = ids.filter(id => isOther(id) && !AMPLIFIER_TYPE_IDS.has(id));\n\n  // Interleave Rep → Spin → Rep → Spin — pairs Repeaters with Spinners as\n  // they're placed, satisfying the adjacency constraint inline.\n  const interleaved = [];\n  while (reps.length || spinners.length) {\n    if (reps.length)     interleaved.push(reps.shift());\n    if (spinners.length) interleaved.push(spinners.shift());\n  }\n  return [...amplifiers, ...others, ...bioOnly, ...interleaved];\n}\n\nfunction buildGreedyInitial(componentIds, grid, prefilledPlacements = []) {\n  const ordered = _saComponentOrder([...componentIds]);\n  const wireDef = componentLib.find(d => d.id === 'wire');\n  const fakeState = {\n    grid: { ...grid },\n    placements: prefilledPlacements.slice(),\n    nextId: prefilledPlacements.length + 1\n  };\n\n  const droppedIds = [];\n  for (const id of ordered) {\n    const def = componentLib.find(d => d.id === id);\n    if (!def) { droppedIds.push(id + ' (def missing)'); continue; }\n    const result = findBestPlacement(def, fakeState);\n    if (!result) {\n      // findBestPlacement is constraint-aware; if it fails, try any geometric fit\n      const anyFit = _saFindAnyFit(def, fakeState);\n      if (!anyFit) {\n        droppedIds.push(id);\n        continue;\n      }\n      fakeState.placements.push({\n        id: fakeState.nextId++, componentId: id,\n        row: anyFit.row, col: anyFit.col, rotation: anyFit.rotation,\n        rotatedShape: anyFit.rotatedShape,\n        rotatedPorts: anyFit.rotatedPorts,\n        rotatedPeripheral: anyFit.rotatedPeripheral\n      });\n      continue;\n    }\n\n    // Add wire path produced by findBestPlacement\n    (result.wirePath || []).forEach(([r, c]) => {\n      if (!wireDef) return;\n      fakeState.placements.push({\n        id: fakeState.nextId++, componentId: 'wire',\n        row: r, col: c, rotation: 0,\n        rotatedShape: [[0,0]],\n        rotatedPorts: wireDef.energyPorts.map(p => ({ cell: [...p.cell], side: p.side })),\n        rotatedPeripheral: null, autoPlaced: true\n      });\n    });\n    fakeState.placements.push({\n      id: fakeState.nextId++, componentId: id,\n      row: result.row, col: result.col, rotation: result.rotation,\n      rotatedShape: result.rotatedShape, rotatedPorts: result.rotatedPorts,\n      rotatedPeripheral: result.rotatedPeripheral\n    });\n  }\n\n  if (droppedIds.length > 0) {\n    console.warn(`[Greedy] ${droppedIds.length} components do not fit in grid ${grid.rows}x${grid.cols}: ${droppedIds.join(', ')}. SA will run with incomplete set.`);\n  }\n  // SA wants non-wires only — it'll rebuild wires every cost evaluation\n  return fakeState.placements.filter(p => p.componentId !== 'wire');\n}\n\n// Fallback: place a component at any non-overlapping position with any rotation.\n// Validates that the component's PERIPHERAL (e.g. Biocell on Bio Generator) also\n// fits within grid bounds and doesn't overlap — otherwise the peripheral would\n// be auto-placed off-grid or onto another component.\nfunction _saFindAnyFit(def, state) {\n  const occupiedMap = getOccupiedMap(state.placements);\n  // Cells reserved by existing placements' peripherals must also be respected\n  const periOccupied = new Set();\n  for (const p of state.placements) {\n    if (!p.rotatedPeripheral) continue;\n    const peri = p.rotatedPeripheral;\n    const d = SIDE_DELTA[peri.port.side];\n    const sR = p.row + peri.port.cell[0] + d.dr;\n    const sC = p.col + peri.port.cell[1] + d.dc;\n    for (const [r, c] of peri.shape) periOccupied.add(`${sR + r},${sC + c}`);\n  }\n  for (const deg of getUniqueDegs(def)) {\n    const { shape, energyPorts } = rotateComponent(def, deg);\n    const rotPeri = buildRotatedPeri(def, deg);\n    const bounds = getBounds(shape);\n    if (bounds.height > state.grid.rows || bounds.width > state.grid.cols) continue;\n    for (let row = 0; row <= state.grid.rows - bounds.height; row++) {\n      for (let col = 0; col <= state.grid.cols - bounds.width; col++) {\n        if (hasOverlap(shape, row, col, occupiedMap)) continue;\n        // Verify peripheral (if any) fits in grid and doesn't collide\n        if (rotPeri) {\n          const d = SIDE_DELTA[rotPeri.port.side];\n          const sR = row + rotPeri.port.cell[0] + d.dr;\n          const sC = col + rotPeri.port.cell[1] + d.dc;\n          let periBad = false;\n          for (const [pr, pc] of rotPeri.shape) {\n            const rr = sR + pr, cc = sC + pc;\n            if (rr < 0 || rr >= state.grid.rows || cc < 0 || cc >= state.grid.cols) { periBad = true; break; }\n            if (occupiedMap.has(`${rr},${cc}`)) { periBad = true; break; }\n            if (periOccupied.has(`${rr},${cc}`)) { periBad = true; break; }\n          }\n          if (periBad) continue;\n        }\n        return {\n          row, col, rotation: deg,\n          rotatedShape: shape,\n          rotatedPorts: energyPorts,\n          rotatedPeripheral: rotPeri\n        };\n      }\n    }\n  }\n  return null;\n}\n\n// Apply N random valid moves to give workers structurally diverse starting points.\n// Each worker calls perturbInitial(state, N) where N depends on workerId.\nfunction perturbInitial(initial, grid, perturbCount) {\n  let current = initial.map(p => ({ ...p }));\n  let applied = 0;\n  let attempts = 0;\n  while (applied < perturbCount && attempts < perturbCount * 50) {\n    attempts++;\n    const next = saGenerateMove(current, grid);\n    if (next) { current = next; applied++; }\n  }\n  return current;\n}\n\n// Two-phase seed: pack a shell along the bus-free N+E edges first, then\n// greedily fill the interior with the remaining components. This is the\n// user's idea — the shell creates an outer scaffold whose inward-facing\n// ports become the connection points for the interior. Greedy fill then\n// uses findBestPlacement (with the shell as obstacles), so interior\n// components naturally cluster near the W/S bus.\nfunction buildShellThenGreedy(nonWireIds, grid) {\n  const { shellPlacements, remaining } = packShell(nonWireIds, grid);\n  // Shell components were placed by packShell — bring them in as prefilled\n  // and greedy-place the rest with shell visible as obstacles.\n  const all = buildGreedyInitial(remaining, grid, shellPlacements);\n  return all;\n}\n\n\n// --- src/sa/annealer.js ---\n// src/sa/annealer.js — Simulated Annealing main loop.\n//\n// State: an array of non-wire placements (positions/rotations/shape).\n// At each step the move generator produces a neighbour state. The neighbour\n// is fully evaluated by adding wires (tryAddWires) and scoring (scoreLayout).\n// Lower cost = better. SA accepts improving moves always, worsening moves\n// with probability e^(-ΔE / T). T cools each iteration.\n//\n// The cost function uses scoreLayout (negated) plus heavy penalties for\n// states that cannot be wired or violate hard constraints.\n\n// Compute SA cost for a placement list (may include cluster placements),\n// returning the intermediate wired/valid/score too — the main loop's\n// accepted-move leaf-check needs exactly these and used to recompute them\n// from scratch via a second tryAddWires+isLayoutValid+scoreLayout pass,\n// doubling the single most expensive part of every accepted iteration\n// (tryAddWires is O(components) BFS passes — see profiling notes below).\n// Clusters are expanded to their individual components before validation —\n// the search treats clusters as atomic placements, but scoring sees them\n// as the individual Spinner/Repeater components they actually are.\nfunction saComputeCostDetailed(nonWirePlacements, grid) {\n  // Expand any cluster placements to individuals (Spinner/Rep_2s/Rep_4s).\n  // If no clusters present, expandClustersInPlacements returns input unchanged.\n  const expanded = (typeof expandClustersInPlacements === 'function')\n    ? expandClustersInPlacements(nonWirePlacements)\n    : nonWirePlacements;\n\n  const wired = tryAddWires(expanded, grid);\n  if (wired) {\n    const valid = isLayoutValid(wired, grid);\n    const score = scoreLayout(wired, grid);\n    const baseCost = -score;\n    return { cost: valid ? baseCost : baseCost + 30000, wired, valid, score };\n  }\n  const poweredSet = computePoweredSet(expanded, grid.rows, grid.cols);\n  let unpowered = 0;\n  for (let i = 0; i < expanded.length; i++) {\n    const p = expanded[i];\n    const def = componentLib.find(d => d.id === p.componentId);\n    if (def && def.energyPorts.length > 0 && !poweredSet.has(i)) unpowered++;\n  }\n  return { cost: 50000 + unpowered * 3000, wired: null, valid: false, score: null };\n}\n\nfunction saComputeCost(nonWirePlacements, grid) {\n  return saComputeCostDetailed(nonWirePlacements, grid).cost;\n}\n\n// Main SA loop. Runs until shouldStop() returns true (no maxIter cap).\n// SA may transiently accept invalid neighbours to escape local minima, but\n// only VALID layouts are reported via reportLeaf — invalid results are useless.\nfunction simulatedAnneal(initialNonWire, grid, options = {}) {\n  const tStart        = options.tStart        ?? 30000;\n  const tEnd          = options.tEnd          ?? 0.1;\n  const coolingRate   = options.coolingRate   ?? 0.9999;\n  const restartAfter  = options.restartAfter  ?? 5000;\n  const progressEvery = options.progressEvery ?? 500;\n  const progressCb    = options.progressCb;\n  const shouldStop    = options.shouldStop;\n  const reportLeaf    = options.reportLeaf;\n\n  let current = initialNonWire.map(p => ({ ...p }));\n  let currentCost = saComputeCost(current, grid);\n  let best = current.map(p => ({ ...p }));\n  let bestCost = currentCost;\n  // Track best VALID layout separately — only this is reported as a result\n  let bestValidCost = Infinity;\n  let bestValidLayout = null;\n  let T = tStart;\n  let lastImprovement = 0;\n  let iter = 0;\n\n  // Run indefinitely until shouldStop signals\n  while (true) {\n    if (shouldStop && shouldStop()) break;\n\n    let neighbour = null;\n    for (let attempt = 0; attempt < 30 && !neighbour; attempt++) {\n      neighbour = saGenerateMove(current, grid);\n    }\n    if (neighbour) {\n      const nDetail = saComputeCostDetailed(neighbour, grid);\n      const nCost = nDetail.cost;\n      const delta = nCost - currentCost;\n      if (delta < 0 || Math.random() < Math.exp(-delta / T)) {\n        current = neighbour;\n        currentCost = nCost;\n        if (currentCost < bestCost) {\n          best = current.map(p => ({ ...p }));\n          bestCost = currentCost;\n          lastImprovement = iter;\n        }\n        // Reuse nDetail's wired/valid/score from the cost computation above\n        // instead of recomputing tryAddWires+isLayoutValid+scoreLayout again.\n        if (nDetail.wired && nDetail.valid && -nDetail.score < bestValidCost) {\n          bestValidCost = -nDetail.score;\n          bestValidLayout = nDetail.wired;\n          if (reportLeaf) reportLeaf(nDetail.wired, nDetail.score);\n        }\n      }\n    }\n\n    T *= coolingRate;\n    if (T < tEnd) T = tEnd;\n\n    // Restart from best if stuck — reheat partially\n    if (iter - lastImprovement > restartAfter) {\n      T = tStart * 0.7;\n      current = best.map(p => ({ ...p }));\n      currentCost = bestCost;\n      lastImprovement = iter;\n    }\n\n    if (progressCb && (iter % progressEvery === 0)) {\n      progressCb(iter, T, currentCost, bestCost, bestValidCost);\n    }\n    iter++;\n  }\n\n  return { placements: best, cost: bestCost, bestValidLayout, bestValidCost, iters: iter };\n}\n\n\n// --- optimizer.js ---\n// optimizer.js – Idle Directive Body Optimizer\n// Rotation helpers moved to src/optimizer/rotation.js.\n// Placement helpers moved to src/optimizer/placement.js.\n// Bus/power/wire helpers (SIDE_DELTA, OPPOSITE, computePoweredSet, findWirePath,\n// wouldConnectToComponent, wouldConnectToBus, wouldBePowered) moved to src/optimizer/bus.js.\n\n// getOccupiedMap, hasOverlap, fitsInGrid moved to src/optimizer/placement.js\n\n// Biocell / Disposable Biocell have normal electrical ports but only\n// function when plugged directly into a Bio Generator (any tier) — a hard\n// placement constraint, same shape as the Repeater<->Spinner/Pulser one.\n// BIOCELL_IDS / BIO_GENERATOR_IDS are defined once in src/optimizer/validate.js\n// (loaded before this file in both index.html and the worker bundle).\nfunction wouldConnectToBioGenerator(energyPorts, row, col, placements) {\n  for (const { cell, side } of energyPorts) {\n    const gr = row + cell[0], gc = col + cell[1];\n    const d = SIDE_DELTA[side];\n    const ar = gr + d.dr, ac = gc + d.dc;\n    for (const pp of placements) {\n      if (!BIO_GENERATOR_IDS.has(pp.componentId)) continue;\n      for (const { cell: pc, side: ps } of (pp.rotatedPorts || [])) {\n        if (pp.row + pc[0] === ar && pp.col + pc[1] === ac && ps === OPPOSITE[side]) return true;\n      }\n    }\n  }\n  return false;\n}\n\n// computePoweredSet, wouldConnect*, wouldBePowered moved to src/optimizer/bus.js\n// addPeripheralReserved moved to src/optimizer/placement.js\n\n// computeFreeSpaceQuality moved to src/optimizer/score.js\n\n// Compact spatial score: shared edges + position bias (no energy, no quality – those are in findBestPlacement)\nfunction scorePositionAndCompact(shape, row, col, occupiedMap, gridRows, gridCols) {\n  let score = 0;\n  const shapeRows = shape.map(([r]) => r);\n  const shapeCols = shape.map(([,c]) => c);\n\n  shape.forEach(([r,c]) => {\n    const gr = row+r, gc = col+c;\n    [[-1,0],[1,0],[0,-1],[0,1]].forEach(([dr,dc]) => {\n      const nr = gr+dr, nc = gc+dc;\n      if (nr < 0 || nr >= gridRows || nc < 0 || nc >= gridCols) score += 5;\n      else if (occupiedMap.has(`${nr},${nc}`)) score += 25;\n    });\n  });\n\n  const avgRow = row + (Math.max(...shapeRows) + Math.min(...shapeRows)) / 2;\n  const avgCol = col + (Math.max(...shapeCols) + Math.min(...shapeCols)) / 2;\n  score -= (avgCol * 3 + (gridRows - 1 - avgRow));\n\n  return score;\n}\n\nfunction buildRotatedPeri(compDef, deg) {\n  if (!compDef.peripheral) return null;\n  const mainMaxR = Math.max(...compDef.shape.map(([r]) => r));\n  const mainMaxC = Math.max(...compDef.shape.map(([,c]) => c));\n\n  // Rotate port cell and side\n  const rotCell = rotateCoord(compDef.peripheral.port.cell[0], compDef.peripheral.port.cell[1], mainMaxR, mainMaxC, deg);\n  const rotSide = rotateSide(compDef.peripheral.port.side, deg);\n\n  // Normalise using the same offset applied to the main shape\n  const rotatedMain = compDef.shape.map(([r,c]) => rotateCoord(r, c, mainMaxR, mainMaxC, deg));\n  const minR = Math.min(...rotatedMain.map(([r]) => r));\n  const minC = Math.min(...rotatedMain.map(([,c]) => c));\n\n  return {\n    port:    { cell: [rotCell[0]-minR, rotCell[1]-minC], side: rotSide },\n    shape:   rotatePeriShape(compDef.peripheral.shape, deg),\n    color:   compDef.peripheral.color,\n    bgColor: compDef.peripheral.bgColor,\n    name:    compDef.peripheral.name\n  };\n}\n\n// Wire-shape stub used for temporary quality calculations\nfunction wireStub(r, c) { return { rotatedShape: [[0,0]], row: r, col: c }; }\n\n// computeWorkingSet moved to src/optimizer/score.js\n\n// Extra placement bonus for repeaters connecting to their valid targets (spinner, pulser).\n// Repeaters are only useful adjacent to these two component types.\nfunction getRepeaterTargetBonus(compDef, energyPorts, row, col, placements) {\n  if (compDef.id !== 'repeater_2s' && compDef.id !== 'repeater_4s') return 0;\n\n  const TARGET_IDS = new Set(['spinner', 'pulser']);\n\n  const portMap = new Map();\n  placements.forEach((p, idx) => {\n    p.rotatedPorts.forEach(({ cell, side }) => {\n      const key = `${p.row+cell[0]},${p.col+cell[1]},${side}`;\n      if (!portMap.has(key)) portMap.set(key, []);\n      portMap.get(key).push(idx);\n    });\n  });\n\n  let bonus = 0;\n  let targetsConnected = 0;\n\n  placements.forEach((sp) => {\n    if (!TARGET_IDS.has(sp.componentId)) return;\n    let touchesThisTarget = false;\n\n    sp.rotatedPorts.forEach(({ cell: sc, side: ss }) => {\n      const sGr = sp.row + sc[0], sGc = sp.col + sc[1];\n      energyPorts.forEach(({ cell: ec, side: es }) => {\n        const eGr = row + ec[0], eGc = col + ec[1];\n        const ed  = SIDE_DELTA[es];\n        if (eGr+ed.dr === sGr && eGc+ed.dc === sGc && OPPOSITE[es] === ss) {\n          bonus += 1500;\n          touchesThisTarget = true;\n          // Extra bonus if completing the 4s pair on the opposite side of spinner/pulser\n          if (compDef.id === 'repeater_4s') {\n            const otherSideHas4s = sp.rotatedPorts.some(({ cell: oc, side: os }) => {\n              if (os === ss) return false;\n              const oGr = sp.row + oc[0], oGc = sp.col + oc[1];\n              const od  = SIDE_DELTA[os];\n              const adjKey = `${oGr+od.dr},${oGc+od.dc},${OPPOSITE[os]}`;\n              return portMap.has(adjKey) &&\n                     portMap.get(adjKey).some(i => placements[i].componentId === 'repeater_4s');\n            });\n            if (otherSideHas4s) bonus += 2000;\n          }\n        }\n      });\n    });\n\n    if (touchesThisTarget) targetsConnected++;\n  });\n\n  // Bonus for one repeater serving two targets simultaneously (minimises repeater count)\n  if (targetsConnected >= 2) bonus += 3000;\n\n  return bonus;\n}\n\n// Bonus for connecting a Power Amplifier to a Harvester/Salvager (or the\n// reverse: placing a Harvester/Salvager next to an already-placed\n// Amplifier). Same relationship computeAmplifierBonus rewards in\n// src/optimizer/score.js for SMART — kept here too so RE-OPTIMIZE's\n// one-component-at-a-time greedy also tries to make the connection.\n// Reads the live scoreWeights.amplifier so both paths agree on magnitude.\nconst AMPLIFIER_TARGET_IDS = new Set(['harvester', 'salvager']);\n\nfunction getAmplifierConnectionBonus(compDef, energyPorts, row, col, placements) {\n  const isAmplifier = compDef.id === 'power_amplifier';\n  const isTarget = AMPLIFIER_TARGET_IDS.has(compDef.id);\n  if (!isAmplifier && !isTarget) return 0;\n\n  let bonus = 0;\n  const counted = new Set();\n  for (const { cell, side } of energyPorts) {\n    const gr = row + cell[0], gc = col + cell[1];\n    const d  = SIDE_DELTA[side];\n    const ar = gr + d.dr, ac = gc + d.dc;\n    for (let j = 0; j < placements.length; j++) {\n      const pp = placements[j];\n      const isMatch = isAmplifier\n        ? AMPLIFIER_TARGET_IDS.has(pp.componentId)\n        : pp.componentId === 'power_amplifier';\n      if (!isMatch || counted.has(j)) continue;\n      const connects = pp.rotatedPorts.some(({ cell: pc, side: ps }) =>\n        pp.row + pc[0] === ar && pp.col + pc[1] === ac && ps === OPPOSITE[side]\n      );\n      if (connects) { counted.add(j); bonus += scoreWeights.amplifier; }\n    }\n  }\n  return bonus;\n}\n\n// Same idea as getAmplifierConnectionBonus, for the other three amplifier-\n// family components (each mirroring its computeXBonus in\n// src/optimizer/score.js, used by SA's scoreLayout) — without these,\n// RE-OPTIMIZE and SA's initial greedy seed never even try to place these\n// near their targets; only SMART's later move-based search would find the\n// connection. AMPLIFIER_TARGET_IDS-style sets (_isBatteryTarget,\n// ENERGY_AMPLIFIER_TARGETS, CONCENTRATOR_TARGETS) are defined once in\n// src/optimizer/score.js (loaded before this file).\n\n// Battery Amplifier <-> any battery, bonus scaled by the battery's cell\n// count — same area-scaling as computeBatteryAmplifierBonus.\nfunction getBatteryAmplifierConnectionBonus(compDef, energyPorts, row, col, placements, shape) {\n  const isAmplifier = compDef.id === 'battery_amplifier';\n  const isTarget = _isBatteryTarget(compDef.id);\n  if (!isAmplifier && !isTarget) return 0;\n\n  let bonus = 0;\n  const counted = new Set();\n  for (const { cell, side } of energyPorts) {\n    const gr = row + cell[0], gc = col + cell[1];\n    const d  = SIDE_DELTA[side];\n    const ar = gr + d.dr, ac = gc + d.dc;\n    for (let j = 0; j < placements.length; j++) {\n      const pp = placements[j];\n      const isMatch = isAmplifier\n        ? _isBatteryTarget(pp.componentId)\n        : pp.componentId === 'battery_amplifier';\n      if (!isMatch || counted.has(j)) continue;\n      const connects = pp.rotatedPorts.some(({ cell: pc, side: ps }) =>\n        pp.row + pc[0] === ar && pp.col + pc[1] === ac && ps === OPPOSITE[side]\n      );\n      if (connects) {\n        counted.add(j);\n        const area = isAmplifier ? pp.rotatedShape.length : shape.length;\n        bonus += scoreWeights.batteryAmplifier * area;\n      }\n    }\n  }\n  return bonus;\n}\n\n// Energy Amplifier <-> Bio Generator/Energy Cells/Spinner/Pulser, one\n// weight per target type (energyAmpBioGen/EnergyCells/Spinner/Pulser).\nfunction _energyAmpWeightFor(id) {\n  if (id === 'bio_generator' || id === 'bio_generator_ii') return scoreWeights.energyAmpBioGen;\n  if (id === 'energy_cells') return scoreWeights.energyAmpEnergyCells;\n  if (id === 'spinner') return scoreWeights.energyAmpSpinner;\n  if (id === 'pulser') return scoreWeights.energyAmpPulser;\n  return 0;\n}\n\nfunction getEnergyAmplifierConnectionBonus(compDef, energyPorts, row, col, placements) {\n  const isAmplifier = compDef.id === 'energy_amplifier';\n  const isTarget = ENERGY_AMPLIFIER_TARGETS.has(compDef.id);\n  if (!isAmplifier && !isTarget) return 0;\n\n  let bonus = 0;\n  const counted = new Set();\n  for (const { cell, side } of energyPorts) {\n    const gr = row + cell[0], gc = col + cell[1];\n    const d  = SIDE_DELTA[side];\n    const ar = gr + d.dr, ac = gc + d.dc;\n    for (let j = 0; j < placements.length; j++) {\n      const pp = placements[j];\n      const isMatch = isAmplifier\n        ? ENERGY_AMPLIFIER_TARGETS.has(pp.componentId)\n        : pp.componentId === 'energy_amplifier';\n      if (!isMatch || counted.has(j)) continue;\n      const connects = pp.rotatedPorts.some(({ cell: pc, side: ps }) =>\n        pp.row + pc[0] === ar && pp.col + pc[1] === ac && ps === OPPOSITE[side]\n      );\n      if (connects) { counted.add(j); bonus += _energyAmpWeightFor(isAmplifier ? pp.componentId : compDef.id); }\n    }\n  }\n  return bonus;\n}\n\n// Concentrator <-> Energy Cells, counted per DISTINCT connected block (same\n// pairing rule as the other 3 amplifier-family bonuses, and as\n// computeConcentratorBonus in src/optimizer/score.js). A block touching the\n// Concentrator via 2 of its own ports still counts once — otherwise 4\n// double-porting blocks (8 port-pairs) score the same as 6 single-porting\n// ones (6 port-pairs) instead of losing to them, which made SA settle for\n// fewer, denser-wired blocks instead of maximizing distinct connections.\nfunction getConcentratorConnectionBonus(compDef, energyPorts, row, col, placements) {\n  const isAmplifier = compDef.id === 'concentrator';\n  const isTarget = CONCENTRATOR_TARGETS.has(compDef.id);\n  if (!isAmplifier && !isTarget) return 0;\n\n  let bonus = 0;\n  const counted = new Set();\n  for (const { cell, side } of energyPorts) {\n    const gr = row + cell[0], gc = col + cell[1];\n    const d  = SIDE_DELTA[side];\n    const ar = gr + d.dr, ac = gc + d.dc;\n    for (let j = 0; j < placements.length; j++) {\n      const pp = placements[j];\n      const isMatch = isAmplifier\n        ? CONCENTRATOR_TARGETS.has(pp.componentId)\n        : pp.componentId === 'concentrator';\n      if (!isMatch || counted.has(j)) continue;\n      const connects = pp.rotatedPorts.some(({ cell: pc, side: ps }) =>\n        pp.row + pc[0] === ar && pp.col + pc[1] === ac && ps === OPPOSITE[side]\n      );\n      if (connects) { counted.add(j); bonus += scoreWeights.concentrator; }\n    }\n  }\n  return bonus;\n}\n\n// Bonus for Spinner/Pulser placed where both port-adjacent cells are free and in-bounds.\n// Encourages the optimizer to leave space for Repeaters on BOTH sides.\nfunction getSpinnerAccessibilityBonus(compDef, energyPorts, row, col, occupiedMap, grid) {\n  if (compDef.id !== 'spinner' && compDef.id !== 'pulser') return 0;\n  let accessible = 0;\n  for (const { cell, side } of energyPorts) {\n    const gr = row + cell[0], gc = col + cell[1];\n    const d  = SIDE_DELTA[side];\n    const ar = gr + d.dr, ac = gc + d.dc;\n    if (ar >= 0 && ar < grid.rows && ac >= 0 && ac < grid.cols && !occupiedMap.has(`${ar},${ac}`)) {\n      accessible++;\n    }\n  }\n  return accessible >= 2 ? 3000 : 0;\n}\n\n// `upgraderPinnedTags`, if given, is the pinnedTags array carried through\n// from the pre-rebuild Upgrader placement (see optimizeAll in app.js) — the\n// candidate search below only accepts positions satisfying\n// _upgraderPortAssignmentOk (src/optimizer/validate.js) against it. Omit\n// for every other component and for an Upgrader with no active pin.\nfunction findBestPlacement(compDef, state, pendingIds = [], upgraderPinnedTags = null) {\n  const { grid, placements } = state;\n  const poweredSet = computePoweredSet(placements, grid.rows, grid.cols);\n  const occupiedMap = getOccupiedMap(placements);\n\n  // Reserve peripheral slots (biocell etc.) — sentinel -1 means \"reserved, not a real component\"\n  placements.forEach(p => {\n    if (!p.rotatedPeripheral) return;\n    const peri = p.rotatedPeripheral;\n    const d    = SIDE_DELTA[peri.port.side];\n    const sR   = p.row + peri.port.cell[0] + d.dr;\n    const sC   = p.col + peri.port.cell[1] + d.dc;\n    peri.shape.forEach(([r, c]) => { const k = `${sR+r},${sC+c}`; if (!occupiedMap.has(k)) occupiedMap.set(k, -1); });\n    const ek = `${sR+d.dr},${sC+d.dc}`; if (!occupiedMap.has(ek)) occupiedMap.set(ek, -1);\n  });\n\n  const isWire = compDef.id === 'wire';\n  const isRepeater = compDef.id === 'repeater_4s' || compDef.id === 'repeater_2s';\n  const isBioCell = BIOCELL_IDS.has(compDef.id);\n  const isPinnedUpgrader = compDef.id === 'upgrader' && upgraderPinnedTags && upgraderPinnedTags.length > 0;\n  const upgraderTargetIdxs = isPinnedUpgrader\n    ? upgraderPinnedTags.map(tag => placements.findIndex(pp => pp.pinTag === tag)).filter(idx => idx !== -1)\n    : [];\n\n  // Pre-compute unworking Spinner ports for the Repeater hard constraint.\n  // Collected once — placements don't change during the search loop.\n  let unworkingSpinnerPorts = [];\n  if (isRepeater) {\n    const ws = computeWorkingSet(placements);\n    placements.forEach((p, i) => {\n      if (p.componentId !== 'spinner' || ws.has(i)) return;\n      p.rotatedPorts.forEach(({ cell, side }) => {\n        unworkingSpinnerPorts.push({ gr: p.row + cell[0], gc: p.col + cell[1], side });\n      });\n    });\n  }\n\n  let bestScore = -Infinity;\n  let bestResult = null;\n\n  for (const deg of [0, 90, 180, 270]) {\n    const { shape, energyPorts } = rotateComponent(compDef, deg);\n    const bounds = getBounds(shape);\n    if (bounds.height > grid.rows || bounds.width > grid.cols) continue;\n\n    const rotPeri = buildRotatedPeri(compDef, deg);\n\n    for (let row = 0; row <= grid.rows - bounds.height; row++) {\n      for (let col = 0; col <= grid.cols - bounds.width; col++) {\n        if (hasOverlap(shape, row, col, occupiedMap)) continue;\n        if (!fitsInGrid(shape, row, col, grid.rows, grid.cols)) continue;\n\n        // ── Hard constraint: Repeater — if any non-working Spinner exists,\n        //    the Repeater MUST connect to it. Otherwise position rejected\n        //    (this is a condition, not a bonus).\n        if (isRepeater && unworkingSpinnerPorts.length > 0) {\n          const connects = unworkingSpinnerPorts.some(({ gr, gc, side }) =>\n            energyPorts.some(({ cell, side: es }) => {\n              const eGr = row + cell[0], eGc = col + cell[1];\n              const d   = SIDE_DELTA[es];\n              return eGr + d.dr === gr && eGc + d.dc === gc && OPPOSITE[es] === side;\n            })\n          );\n          if (!connects) continue;\n        }\n\n        // ── Hard constraint: Spinner ONLY — feasibility check for pending Repeaters ──\n        // Checks not just free slots but whether Spinner CAN ever become functional.\n        // Example: with pending4s=1 and no adjacent 4s yet, adj4sSides+pending4s=1 < 2\n        //          → impossible to reach working state → reject this position.\n        // Pulser: Repeaters are optional (connect if port is free, not mandatory)\n        if (compDef.id === 'spinner') {\n          const pending4s = pendingIds.filter(id => id === 'repeater_4s').length;\n          const pending2s = pendingIds.filter(id => id === 'repeater_2s').length;\n          if (pending4s > 0 || pending2s > 0) {\n            let adj4sSideSet = new Set(), hasAdj2s = false, accessible = 0;\n            for (const { cell, side } of energyPorts) {\n              const gr = row + cell[0], gc = col + cell[1];\n              const d  = SIDE_DELTA[side];\n              const ar = gr + d.dr, ac = gc + d.dc;\n              if (ar < 0 || ar >= grid.rows || ac < 0 || ac >= grid.cols) continue;\n              for (const pp of placements) {\n                for (const { cell: pc, side: ps } of (pp.rotatedPorts || [])) {\n                  if (pp.row + pc[0] === ar && pp.col + pc[1] === ac && ps === OPPOSITE[side]) {\n                    if (pp.componentId === 'repeater_4s') adj4sSideSet.add(side);\n                    if (pp.componentId === 'repeater_2s') hasAdj2s = true;\n                  }\n                }\n              }\n              if (!occupiedMap.has(`${ar},${ac}`)) accessible++;\n            }\n            if (!hasAdj2s && adj4sSideSet.size < 2) {\n              const canWork2s = pending2s > 0;\n              const canWork4s = adj4sSideSet.size + pending4s >= 2;\n              if (!canWork2s && !canWork4s) continue; // structurally impossible\n              const neededFree = canWork2s ? 1 : Math.max(0, 2 - adj4sSideSet.size);\n              if (accessible < neededFree) continue;\n            }\n          }\n        }\n\n        // ── Hard constraint: Biocell / Disposable Biocell — must be\n        //    port-adjacent to a Bio Generator (any tier) to function at all.\n        if (isBioCell && !wouldConnectToBioGenerator(energyPorts, row, col, placements)) continue;\n\n        // ── Hard constraint: pinned Upgrader — must land with its pinned\n        //    port(s) adjacent to their exact target instance(s); any other\n        //    port must not touch a different real component.\n        if (isPinnedUpgrader) {\n          if (upgraderTargetIdxs.length !== upgraderPinnedTags.length) continue; // a target vanished — caller should have filtered this out\n          if (!_upgraderPortAssignmentOk(energyPorts, row, col, placements, upgraderTargetIdxs, null)) continue;\n        }\n\n        // ── Energy/bio connection priority ────────────────────────────────\n        let energyBonus = 0;\n        let wirePath    = [];\n\n        if (wouldConnectToComponent(energyPorts, row, col, placements, poweredSet)) {\n          energyBonus = 2000;\n        } else if (wouldConnectToBus(energyPorts, row, col, grid.rows, grid.cols)) {\n          energyBonus = 1000;\n        } else if (isWire) {\n          energyBonus = 0; // wires may be placed anywhere; will receive power transitively\n        } else if (compDef.id === 'spinner' || compDef.id === 'pulser') {\n          energyBonus = 0; // powered by adjacent Repeaters placed after them\n        } else {\n          const path = findWirePath(shape, energyPorts, row, col, state);\n          if (path === null) continue; // no power path → skip this position\n          wirePath    = path;\n          // Wire count is top priority: penalty >> max possible quality gain\n          energyBonus = 800 - wirePath.length * 5000;\n        }\n\n        // ── Free space quality AFTER placing component + wires ────────────\n        // Temporarily add wire stubs so quality reflects final occupied state\n        const tempPlacements = wirePath.length > 0\n          ? [...placements, ...wirePath.map(([r,c]) => wireStub(r, c))]\n          : placements;\n        const quality = computeFreeSpaceQuality(shape, row, col, tempPlacements, grid.rows, grid.cols);\n\n        // ── Compact + position ────────────────────────────────────────────\n        const spatial = scorePositionAndCompact(shape, row, col, occupiedMap, grid.rows, grid.cols);\n\n        // ── Peripheral edge bonus ─────────────────────────────────────────\n        let periBonus = 0;\n        if (rotPeri) {\n          const gr = row + rotPeri.port.cell[0], gc = col + rotPeri.port.cell[1];\n          const s  = rotPeri.port.side;\n          if ((s === 'E' && gc === grid.cols - 1) || (s === 'W' && gc === 0) ||\n              (s === 'N' && gr === 0)             || (s === 'S' && gr === grid.rows - 1)) {\n            periBonus = 600;\n          }\n        }\n\n        // ── Repeater target bonus (spinner / pulser adjacency) ───────────\n        const repeaterBonus = getRepeaterTargetBonus(compDef, energyPorts, row, col, placements);\n\n        // ── Spinner/Pulser accessibility bonus ────────────────────────────\n        // Prefers positions where BOTH port sides have free adjacent cells for Repeaters\n        const spinnerBonus = getSpinnerAccessibilityBonus(compDef, energyPorts, row, col, occupiedMap, grid);\n\n        // ── Amplifier-family connection bonuses ──────────────────────────\n        const amplifierBonus = getAmplifierConnectionBonus(compDef, energyPorts, row, col, placements);\n        const batteryAmpBonus = getBatteryAmplifierConnectionBonus(compDef, energyPorts, row, col, placements, shape);\n        const energyAmpBonus = getEnergyAmplifierConnectionBonus(compDef, energyPorts, row, col, placements);\n        const concentratorBonus = getConcentratorConnectionBonus(compDef, energyPorts, row, col, placements);\n\n        // ── Total score ───────────────────────────────────────────────────\n        const score = energyBonus + quality * 4 + spatial + periBonus + repeaterBonus + spinnerBonus\n                     + amplifierBonus + batteryAmpBonus + energyAmpBonus + concentratorBonus;\n\n        if (score > bestScore) {\n          bestScore = score;\n          bestResult = {\n            row, col, rotation: deg,\n            rotatedShape: shape, rotatedPorts: energyPorts,\n            rotatedPeripheral: rotPeri,\n            wirePath\n          };\n        }\n      }\n    }\n  }\n\n  return bestResult;\n}\n\n// Find the shortest path of wire cells needed to connect a component (at row,col) to power.\n// Returns [{r,c}, ...] of cells where wires must be placed, or null if unreachable.\n// findWirePath moved to src/optimizer/bus.js\n\n\n// --- sa-worker.js ---\n// sa-worker.js — Simulated Annealing in a Web Worker.\n// Seed strategy: Shell pack (N+E edges) → greedy fill interior → per-worker\n// perturbation → SA. This guarantees each worker starts at a valid (or near-\n// valid) layout AND at structurally distinct points in the search space.\n//\n// Message protocol:\n//   Main → Worker:\n//     {type:'init', componentLib, scoreWeights}             → 'ready'\n//     {type:'start', nonWireIds, grid, options, workerId}  — begin\n//     {type:'stop'}                                        — cancel\n//   Worker → Main:\n//     {type:'ready'}\n//     {type:'progress', workerId, iter, T, currentCost, bestCost, bestValidCost, elapsedMs}\n//     {type:'leaf', workerId, layout, score, isFirst}      — VALID layout improvement\n//     {type:'stopped', workerId}\n//     {type:'error', message}\n\nlet componentLib = [];\nlet stopRequested = false;\nlet activeRun = false;\n\nself.onmessage = function (e) {\n  const msg = e.data;\n  switch (msg.type) {\n    case 'init':\n      componentLib = msg.componentLib;\n      if (msg.scoreWeights) setScoreWeights(msg.scoreWeights);\n      self.postMessage({ type: 'ready' });\n      break;\n    case 'start':\n      if (activeRun) { self.postMessage({ type: 'error', message: 'already running' }); return; }\n      stopRequested = false;\n      activeRun = true;\n      runSA(msg);\n      break;\n    case 'stop':\n      stopRequested = true;\n      break;\n  }\n};\n\n// Per-worker strategy: each worker gets a distinct combination of\n//   (move bias profile, perturbation count)\n// so all six explore the search space from structurally different points.\nconst WORKER_PROFILES = [\n  { bias: 'balanced', perturb:  0 }, // worker 0: clean shell+greedy, balanced moves\n  { bias: 'local',    perturb:  3 }, // worker 1: slight perturb, fine-tune\n  { bias: 'rotate',   perturb:  8 }, // worker 2: rotation-focused, mid perturb\n  { bias: 'swap',     perturb: 12 }, // worker 3: swap-focused, more perturb\n  { bias: 'jump',     perturb: 18 }, // worker 4: aggressive relocate, big perturb\n  { bias: 'balanced', perturb: 25 }  // worker 5: balanced moves, very different start\n];\n\nfunction runSA(params) {\n  const { nonWireIds, grid, workerId = 0, initialPlacements } = params;\n  const options = params.options || {};\n  const startTime = Date.now();\n\n  const profile = WORKER_PROFILES[workerId % WORKER_PROFILES.length];\n  setSaMoveBias(profile.bias);\n  console.log(`[SA worker ${workerId}] Profile: bias=${profile.bias}, perturb=${profile.perturb}`);\n\n  // === Phase 0a: Register cluster defs for ALL workers. ===\n  // Even workers that start from user's state will benefit from registered\n  // cluster defs (SA's relocate-move can introduce clusters during search).\n  const allClusterDefs = enumerateAllClusterDefs(nonWireIds);\n  registerClusterDefs(allClusterDefs);\n  console.log(`[SA worker ${workerId}] Registered ${allClusterDefs.length} cluster def variants`);\n\n  // === Phase 0b: Seed selection priority ===\n  //   1. User's current layout if structurally sane (bounds + no overlap).\n  //      Wire-validity NOT required — SA's cost function handles invalid\n  //      states with a penalty; what matters is preserving the full component\n  //      count so SA never reports a leaf with fewer components than the user has.\n  //   2. Multi-strategy greedy chain: each tries to place ALL components;\n  //      next strategy fires if any are dropped.\n  let seed = null;\n  let seedExpanded = null;\n  let seedWired = null;\n  let seedValid = false;\n  let seedScore = -Infinity;\n  let seedSource = '';\n\n  function _isUserSeedSane(userSeed) {\n    const occupied = new Set();\n    for (const p of userSeed) {\n      if (!p.rotatedShape) return false;\n      for (const [r, c] of p.rotatedShape) {\n        const gr = p.row + r, gc = p.col + c;\n        if (gr < 0 || gr >= grid.rows || gc < 0 || gc >= grid.cols) return false;\n        const key = `${gr},${gc}`;\n        if (occupied.has(key)) return false;\n        occupied.add(key);\n      }\n      // Peripheral cells (Biocell etc.) must also fit in grid + not overlap\n      if (p.rotatedPeripheral) {\n        const peri = p.rotatedPeripheral;\n        const d = SIDE_DELTA[peri.port.side];\n        const sR = p.row + peri.port.cell[0] + d.dr;\n        const sC = p.col + peri.port.cell[1] + d.dc;\n        for (const [r, c] of peri.shape) {\n          const gr = sR + r, gc = sC + c;\n          if (gr < 0 || gr >= grid.rows || gc < 0 || gc >= grid.cols) return false;\n          const key = `${gr},${gc}`;\n          if (occupied.has(key)) return false;\n          occupied.add(key);\n        }\n      }\n    }\n    return true;\n  }\n\n  if (initialPlacements && initialPlacements.length > 0) {\n    const userSeedExpanded = initialPlacements.map(p => ({\n      componentId: p.componentId,\n      row: p.row, col: p.col, rotation: p.rotation,\n      rotatedShape: p.rotatedShape,\n      rotatedPorts: p.rotatedPorts,\n      rotatedPeripheral: p.rotatedPeripheral,\n      pinTag: p.pinTag, pinnedTags: p.pinnedTags // Upgrader pin identity — see isLayoutValid's _upgraderPinsOk\n    }));\n    if (_isUserSeedSane(userSeedExpanded)) {\n      // Freeze Upgrader pin-groups and amplifier-family clusters (Concentrator\n      // + connected Energy Cells etc.) into rigid merged blocks BEFORE handing\n      // the seed to SA's move set — see mergeConnectedGroupsIntoBlocks in\n      // src/sa/clusters.js. Stronger than the optional chain-move (v=155):\n      // a merged block is the ONLY placement SA's move set sees for that\n      // group, so no single-piece move can ever break its connections, and\n      // the search operates on far fewer, bigger atoms.\n      const userSeed = mergeConnectedGroupsIntoBlocks(userSeedExpanded);\n      seed = userSeed;             // SA-level (may contain merged blocks)\n      seedExpanded = userSeedExpanded; // individual placements for scoring/wiring\n      seedWired = tryAddWires(userSeedExpanded, grid);\n      seedValid = seedWired && isLayoutValid(seedWired, grid);\n      seedScore = seedValid ? scoreLayout(seedWired, grid) : -Infinity;\n      seedSource = seedValid\n        ? `user layout (${userSeedExpanded.length} components, valid, ${userSeed.length} atoms after merge)`\n        : `user layout (${userSeedExpanded.length} components, invalid — SA will fix)`;\n    }\n  }\n\n  if (!seed) {\n    // Multi-strategy fallback chain. Each strategy returns expanded placements.\n    const targetCount = nonWireIds.length;\n    const allDecompositions = enumerateDecompositions(nonWireIds);\n    const decomposition = pickDecompositionForWorker(allDecompositions, workerId);\n    const effectiveIds = substituteClusterIds(nonWireIds, decomposition);\n    const desc = decomposition.clusters.length > 0\n      ? decomposition.clusters.map(c => `${c.pattern}${c.spinners}`).join(' + ')\n      : '(no clusters)';\n    console.log(`[SA worker ${workerId}] Decomposition: ${desc} (from ${nonWireIds.length} IDs to ${effectiveIds.length})`);\n\n    // Each strategy: build returns SA-level placements (may contain clusters),\n    // expand returns the post-expansion individual list (for the count check).\n    // SA needs the un-expanded seed so moves operate on clusters as atoms.\n    const strategies = [\n      { name: `shell+greedy with ${desc}`,\n        build: () => buildShellThenGreedy(effectiveIds, grid),\n        expand: (s) => expandClustersInPlacements(s) },\n      { name: 'shell+greedy no clusters',\n        build: () => buildShellThenGreedy(nonWireIds, grid),\n        expand: (s) => s },\n      { name: 'pure greedy no clusters',\n        build: () => buildGreedyInitial(nonWireIds, grid, []),\n        expand: (s) => s }\n    ];\n\n    let chosen = null;\n    for (const strat of strategies) {\n      try {\n        const candidate = strat.build();\n        const expanded = candidate ? strat.expand(candidate) : null;\n        const placed = expanded ? expanded.length : 0;\n        if (placed >= targetCount) {\n          chosen = { seed: candidate, expanded, source: strat.name };\n          break;\n        }\n        console.log(`[SA worker ${workerId}] ${strat.name}: ${placed}/${targetCount} fit → trying next strategy.`);\n      } catch (e) {\n        console.warn(`[SA worker ${workerId}] ${strat.name} threw: ${e.message}`);\n      }\n    }\n\n    if (!chosen) {\n      activeRun = false;\n      self.postMessage({\n        type: 'error', workerId,\n        message: `Cannot place all ${targetCount} components in grid ${grid.rows}x${grid.cols}. Expand body or reduce set.`\n      });\n      return;\n    }\n\n    seed = chosen.seed;            // SA-level (may contain clusters)\n    seedExpanded = chosen.expanded; // individual placements for scoring/wiring\n    seedWired = tryAddWires(seedExpanded, grid);\n    seedValid = seedWired && isLayoutValid(seedWired, grid);\n    seedScore = seedValid ? scoreLayout(seedWired, grid) : -Infinity;\n    seedSource = chosen.source;\n  }\n  console.log(`[SA worker ${workerId}] Seed: ${seedSource}, valid=${seedValid}, score=${seedScore}, count=${seedExpanded.length}`);\n\n  // === Phase 2: perturb for structural diversity ===\n  const perturbed = profile.perturb > 0 ? perturbInitial(seed, grid, profile.perturb) : seed;\n  const pExpanded = expandClustersInPlacements(perturbed);\n  const pWired = tryAddWires(pExpanded, grid);\n  const pValid = pWired && isLayoutValid(pWired, grid);\n  const pScore = pValid ? scoreLayout(pWired, grid) : -Infinity;\n  console.log(`[SA worker ${workerId}] Po perturbaci: valid=${pValid}, score=${pScore}`);\n\n  let bestKnownCost = Infinity;\n  let bestKnownLayout = null;\n\n  // If the seed itself is already valid, report it immediately so the user\n  // sees something on screen within ~100 ms instead of waiting for SA.\n  if (seedValid) {\n    bestKnownCost = -seedScore;\n    bestKnownLayout = seedWired;\n    self.postMessage({ type: 'leaf', workerId, layout: seedWired, score: seedScore, isFirst: true });\n  }\n\n  // === Phase 3: SA from perturbed state ===\n  simulatedAnneal(perturbed, grid, {\n    tStart:        options.tStart        || 30000,\n    tEnd:          options.tEnd          || 0.1,\n    coolingRate:   options.coolingRate   || 0.99997,\n    restartAfter:  options.restartAfter  || 5000,\n    progressEvery: options.progressEvery || 500,\n    shouldStop:    () => stopRequested,\n    progressCb: (iter, T, currentCost, bestCost, bestValidCost) => {\n      self.postMessage({\n        type: 'progress', workerId,\n        iter, T, currentCost, bestCost, bestValidCost,\n        elapsedMs: Date.now() - startTime\n      });\n    },\n    reportLeaf: (wiredLayout, score) => {\n      const isFirst = (bestKnownLayout === null);\n      bestKnownLayout = wiredLayout;\n      bestKnownCost = -score;\n      self.postMessage({ type: 'leaf', workerId, layout: wiredLayout, score, isFirst });\n    }\n  });\n\n  activeRun = false;\n  self.postMessage({ type: 'stopped', workerId });\n}\n"], { type: 'application/javascript' })
);
